// Feature: find_skill (#12). Most skills are left out of the main agent's
// listing (features/skills.ts, ADR 0002), so when, partway through a turn,
// the work turns out to need a skill nobody suggested, the main agent can ask:
// it calls the tool with a few words on the work, and the decision model rates
// the session's skills against them, the same way it rates them beside a
// message (the same ranker, `modRanker`, in the same two stages (#11), over the
// same skills and their profiles, with the recent conversation read by the
// same rules). Nothing is pushed: the skills come back only as the tool's
// answer.
//
// Its switch is `find-skill` (`/dp find-skill off`), apart from `skills`
// (spec #56). The tool stays registered whatever the switches say, with a
// description that never changes (the tool list is part of the prompt cache);
// switched off, it says so when called.

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { type Asked, describeAsked, errorText } from '../decision/backend.ts'
import { turnStartState } from '../decision/context.ts'
import { quoteStart } from '../decision/redact.ts'
import { modRanker, pickSkills, skillOpening, type SkillPick, type SkillPolicy, type SkillRanking } from '../decision/skills.ts'
import { answersFor, mergeParts, type DecisionRequest } from '../decision/system-one.ts'
import { recordDecision } from '../core/decisions.ts'
import { readSessionSkills } from '../core/profiles.ts'
import type { Ctx } from '../core/setup.ts'
import { describeStages, rankingSettings, type CatalogSkill } from '../core/skills.ts'
import { failureText, setStatus } from '../core/status.ts'
import { defineSwitch, isOn, masterOn } from '../core/switches.ts'

const CATALOG = { plugin: 'dispatch-pilot', key: 'skillCatalog' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const

/** The switch's name, in `/dp` and in the decision log. */
const SWITCH = 'find-skill'
/** The skills feature's switch for profiles (#11): off, skills are rated by their descriptions here too. */
const PROFILES = 'skill-profiles'
/** The tool's name; the model calls it as `mcp__dispatch-pilot__find_skill`. */
const TOOL = 'find_skill'
const TOOL_CALLED = 'mcp__dispatch-pilot__find_skill'

/** What the model reads about the tool. Fixed: nothing of the session goes into it. */
const DESCRIPTION =
  "Searches this session's skills for the ones that fit a piece of work, and returns each one's exact name, its relevance (0 to 1) and what it is for. Use it when the work at hand might have a skill you have not been shown: a file format, a service or its tooling, or a way of working such as reviewing, planning, testing or releasing. Load a skill it returns with the Skill tool by that exact name. Skills only the user can start are never returned."
const INPUT = {
  type: 'object',
  properties: {
    query: {
      type: 'string',
      description: 'The kind of work you need a skill for, in a few words, such as "fill in a form in a PDF file" or "review a branch before merging".',
    },
  },
  required: ['query'],
  additionalProperties: false,
}
/** How an answer that brings no skill ends: the main agent's way on. */
const CARRY_ON = 'Carry on without it, or load a skill you know with the Skill tool by its exact name.'

/**
 * The session's skills: as read earlier this session (the skills feature
 * reads them at its start), else read now, with the profiles the store holds
 * (#11), and kept for the session; null when the session cannot be read.
 */
async function sessionCatalog($: EngineInterface, model: string): Promise<CatalogSkill[] | null> {
  const { value } = await $.state.get(CATALOG)
  if (value) return value.skills
  const found = await readSessionSkills(
    {
      commands: () => $.command.list(),
      listed: async () => (await $.session.usage({ breakdown: 'summary' })).context.breakdown?.skills?.skillFrontmatter ?? [],
      overrides: async (source) => (await $.settings.read({ source })).skillOverrides,
      home: () => $.env.get('HOME'),
      cwd: () => $.session.cwd(),
      exists: (path) => $.fs.exists(path),
      read: (path) => $.fs.read(path),
      list: (path) => $.fs.list(path),
      get: (key) => $.store.get(key),
    },
    model,
  )
  if (found !== null) await $.state.set(CATALOG, { skills: found.skills })
  return found?.skills ?? null
}

/** One decision request for find_skill through the person's decision model, its outcome in the debug log. */
async function askLogged($: EngineInterface, ctx: Ctx, what: string, about: string, request: DecisionRequest, timeoutMs: number): Promise<Asked> {
  const io = { fetch: (url: string, init: HttpInit) => $.http.fetch(url, init), sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }) }
  const startedAt = await $.clock.now()
  const asked = await ctx.backend.ask(io, request, timeoutMs)
  const ms = (await $.clock.now()) - startedAt
  $.ui.log(`${what} [${Object.keys(request.questions).join(', ')}] to ${ctx.backend.name} ${about}: ${describeAsked(asked, ms)}`, { to: 'debug' })
  return asked
}

/** The opening of a catalog skill's SKILL.md for the ranking's second stage; null when it has no file. */
async function openingOf($: EngineInterface, catalog: readonly CatalogSkill[], name: string): Promise<string | null> {
  const file = catalog.find((skill) => skill.name === name)?.file ?? null
  return file === null ? null : skillOpening(await $.fs.read(file))
}

export function registerFindSkill(on: On, ctx: Ctx): void {
  defineSwitch({ name: SWITCH, info: "answers the main agent's find_skill: the skills that fit the work it names", segments: ['find-skill'] })

  /** Skills never offered (the option the skills feature reads too). */
  const neverSuggested = new Set(ctx.config.skills.neverSuggested)
  const policy: SkillPolicy = ctx.config.skills.find
  /** How the mod's ranker ranks: the settings it rates the skills beside each message with. */
  const rankBy = rankingSettings(ctx)
  /** The model whose profiles the skills are offered by (#11). */
  const model = ctx.config.skills.profileModel
  /** How long the call's two requests may take in all, and whether the first offers skills by their profiles: the decision model's. */
  const { findWaitMs: waitMs, findByProfile } = ctx.config.skills

  // Registered once every plugin is loaded, under a match-all matcher (other
  // features set themselves up at session start too). Without a decision
  // model nothing could rate the skills, and the main agent keeps its listing.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (ctx.backend.configured === false) return result
    try {
      const { tool } = await $.tool.register({ name: TOOL, description: DESCRIPTION, inputSchema: INPUT })
      if (tool !== TOOL_CALLED) $.ui.log(`find_skill is registered as ${tool}, but the hook answers ${TOOL_CALLED}: its calls will fail`, { to: 'debug' })
    } catch (error) {
      $.ui.log(`find_skill was not registered: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })

  // The model's call: answered here, never passed on. Whatever goes wrong,
  // the answer says so at once (fail open: the turn goes on without a skill).
  on('tool.call', { tool: TOOL_CALLED }, async ($, e) => {
    if (!masterOn()) return { result: `Dispatch Pilot is switched off (/dp on turns it back on), so find_skill rated no skills. ${CARRY_ON}` }
    if (!isOn(SWITCH)) return { result: `find_skill is switched off (/dp ${SWITCH} on turns it back on), so it rated no skills. ${CARRY_ON}` }
    // A dispatched agent's listing is left whole (ADR 0002): it has every skill in view.
    if (e.agentId !== undefined) {
      return { result: "find_skill rates skills for the main agent, whose skill listing is cut short. Yours lists this session's skills: pick from it and load one with the Skill tool by its exact name." }
    }
    const query = typeof e.query === 'string' ? e.query.replace(/\s+/g, ' ').trim() : ''
    if (query === '') return { result: 'find_skill needs a query: a few words on the kind of work you need a skill for.' }
    const show = (text: string) => setStatus('find-skill', text, (line) => $.ui.status(line))
    try {
      // The skills the main agent can load, as a message asks about them: their question of stage
      // one is the very one beside a message (those only the person can start have one of their
      // own, which is not asked: they never come back); each by its profile, as beside a message,
      // unless profiles are switched off.
      const known = await sessionCatalog($, model)
      const candidates = known?.filter((skill) => skill.by === 'model' && !neverSuggested.has(skill.name)).map((skill) => (isOn(PROFILES) ? skill : { ...skill, profile: null })) ?? null
      if (candidates === null) {
        show("find_skill failed (the session's skills could not be read)")
        return { result: `find_skill could not read this session's skills. ${CARRY_ON}` }
      }
      const about = `for find_skill ${quoteStart(query)}`
      const ranker = modRanker(
        {
          ask: (request, timeoutMs) => askLogged($, ctx, 'second request', about, request, timeoutMs),
          opening: (option) => openingOf($, candidates, option.name),
        },
        rankBy,
      )
      // The first request offers each skill by its profile where the decision model can read them all in time
      // (BACKEND_DEFAULTS findSkillProfiles: not Clef), else by its description; the second re-reads by both.
      const part = ranker.part(findByProfile ? candidates : candidates.map((skill) => ({ ...skill, profile: null })))
      if (part === null) {
        show('find_skill none')
        return { result: `This session has no skill that find_skill could return. ${CARRY_ON}` }
      }

      // The same state as beside a message, the work named in place of the message; the ranker's second
      // request (#11) asks about the same. Both requests share one wait: the second gets what the first left
      // of it. The wait is the decision model's (findWaitMs: a message's timeoutMs with Jev, 8000 ms with Clef),
      // within the hook's own 10 s.
      const startedAt = await $.clock.now()
      const messages = ctx.config.context.messages > 0 ? await $.session.messages().catch(() => []) : []
      const request = mergeParts(turnStartState({ prompt: query, messages, limits: ctx.config.context }), [part])
      const asked = await askLogged($, ctx, 'request', about, request, waitMs)
      const left = waitMs - ((await $.clock.now()) - startedAt)
      const ranked = asked.ok ? await ranker.rank(answersFor(part, asked.answers), candidates, { state: request.state, timeoutMs: left }) : null
      const failure = !asked.ok ? asked.failure : ranked === null ? { kind: 'parse' as const, detail: 'no answer about the skills' } : ranked.failed
      if (ranked === null || failure !== undefined) {
        const why = failureText(ctx.backend.name, failure ?? { kind: 'parse', detail: 'no answer about the skills' })
        show(`find_skill failed (${why})`)
        return { result: `find_skill could not rate the skills (${why}). ${CARRY_ON}` }
      }
      const ranking = ranked

      // Only skills the main agent can load were asked about, and they alone can come back.
      const { suggest } = pickSkills(ranking, candidates, policy)
      const names = suggest.map((skill) => skill.name).join(', ')
      await recordDecision(
        { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
        (line) => $.ui.log(line, { to: 'debug' }),
        { feature: SWITCH, outcome: suggest.length > 0 ? `found ${names}` : 'found no skill', about: quoteStart(query), reason: describeRanking(ranking, policy) },
      )
      show(`find_skill ${suggest.length > 0 ? names : 'none'}`)
      return { result: found(query, suggest, policy) }
    } catch (error) {
      $.ui.log(`find_skill failed: ${errorText(error)}`, { to: 'debug' })
      show('find_skill failed (see the debug log)')
      return { result: `find_skill could not rate the skills (an error in Dispatch Pilot, written to the debug log). ${CARRY_ON}` }
    }
  })
}

/** Why: what each stage of the ranking said (`describeStages`), and the bar a skill had to reach. */
function describeRanking(ranking: SkillRanking, policy: SkillPolicy): string {
  return `${describeStages(ranking)}; returned from ${policy.minRelevance.toFixed(2)}, at most ${policy.max}`
}

/** The answer: the skills that fit, each by name, relevance and description, most relevant first; or that none does. */
function found(query: string, suggest: readonly SkillPick[], policy: SkillPolicy): string {
  if (suggest.length === 0) {
    return `No skill fits "${query}": none reached relevance ${policy.minRelevance.toFixed(2)}. Carry on without one, try other words for the work, or load a skill you know with the Skill tool by its exact name.`
  }
  return [
    `Skills that fit "${query}", rated by Dispatch Pilot’s decision model (relevance 0 to 1), most relevant first. Load one with the Skill tool by its exact name if it fits the work:`,
    ...suggest.map((skill) => `- ${skill.name} (relevance ${skill.relevance.toFixed(2)})${skill.description ? `: ${skill.description}` : ''}`),
  ].join('\n')
}

files.hooks/features/main-effort.ts:
// Feature: the main agent's effort, decided each time the person sends a
// message, and when a report starts a turn of its own: a dispatched agent's
// hand-back or a background task's notice reaching the idle session (those
// turns are usually a look at a result and the next dispatch; the session's own
// effort would be a waste). It adds the effort question to the message's ballot
// (the core sends it); the answer becomes the effort of the turn the message
// starts, on every step of that turn (the core's turn.step writer). A report's
// text is read as the message; its turn is not re-decided mid-turn.
//
// A message typed while a turn runs (`e.turnId`) is delivered into that turn
// at its next step (a `queued_command` attachment; measured on 2.1.289), so
// its decision takes the running turn from then on. It also waits as pending,
// in case the turn ends first and the message starts a turn of its own.

import type { On } from 'claude-code'
import { EFFORTS, LEVEL, pickEffort, readEffort, readingText, turnStartEffortPart, type Effort, type EffortReading } from '../decision/effort.ts'
import { quoteStart } from '../decision/redact.ts'
import { contribute } from '../core/ballot.ts'
import { recordDecision } from '../core/decisions.ts'
import { addPending, revise, turnKey, update, type Cell, type PendingDecision, type TurnRecord } from '../core/plans.ts'
import { isPersonsMessage, startsReportTurn } from '../core/prompts.ts'
import type { Ctx } from '../core/setup.ts'
import { failureText, setStatus } from '../core/status.ts'
import { defineSwitch, isOn } from '../core/switches.ts'

const PENDING = { plugin: 'dispatch-pilot', key: 'pending' } as const
const TURNS = { plugin: 'dispatch-pilot', key: 'turns' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const

export function registerMainEffort(on: On, ctx: Ctx): void {
  defineSwitch({ name: 'main-effort', info: "decides the main agent's effort when you send a message", segments: ['decision'] })

  on('prompt.submit', { text: /(?:)/ }, async ($, e, next) => {
    // The person's own message, or a report that starts a turn of its own (a dispatched agent's hand-back, a task notice).
    const report = !isPersonsMessage(e) && startsReportTurn(e)
    if ((!isPersonsMessage(e) && !report) || !isOn('main-effort')) return next(e)
    const pending: Cell<PendingDecision[]> = { get: () => $.state.get(PENDING), set: (value, options) => $.state.set(PENDING, value, options) }
    let added: PendingDecision | null = null

    /** The message waits for its turn, decided or not: the turn it starts is the person's own (mid-turn re-decisions are for such turns). */
    const wait = async (effort: Effort | null) => {
      const entry: PendingDecision = { text: e.text, effort, at: await $.clock.now(), ...(report ? { report: true as const } : {}) }
      await update(pending, (list) => addPending(list ?? [], entry))
      added = entry
    }

    contribute(e.text, {
      // Written in the decision model's language for this question (Chinese with Jev); the other questions keep ctx.ask's.
      ...turnStartEffortPart({ ...ctx.ask, language: ctx.config.turnStartLanguage }),
      settle: async (outcome) => {
        const show = (line: string | undefined) => $.ui.status(line)
        if (!outcome.ok) {
          setStatus('decision', failureText(ctx.backend.name, outcome.failure), show)
          await wait(null)
          return
        }
        const reading = readEffort(outcome.answers[LEVEL])
        if (reading === null) {
          setStatus('decision', failureText(ctx.backend.name, { kind: 'parse', detail: 'no effort answer' }), show)
          await wait(null)
          return
        }
        setStatus('decision', null, show)
        const effort = pickEffort(reading, ctx.config.thetaMax)
        await recordDecision(
          { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
          (line) => $.ui.log(line, { to: 'debug' }),
          { feature: report ? 'main-effort (agent report)' : 'main-effort', outcome: `effort ${effort}`, about: quoteStart(e.text), reason: describeReading(reading, effort, ctx.config.thetaMax) },
        )
        await wait(effort)
        const running = e.turnId
        if (running !== undefined) {
          const ref = { ...TURNS, id: turnKey(running, undefined) }
          const turn: Cell<TurnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
          await update(turn, (record) => revise(record, effort))
        }
      },
    })

    const result = await next(e)
    // Refused beneath: no turn will take this decision.
    const withdrawn = added as PendingDecision | null
    if (result.drop !== undefined && withdrawn !== null) {
      await update(pending, (list) => (list ?? []).filter((entry) => !(entry.text === withdrawn.text && entry.at === withdrawn.at)))
    }
    return result
  })
}

/** Why a level was picked: every level's probability, `max` held back below thetaMax when it was the most likely, and the backend's confidence. */
function describeReading(reading: EffortReading, picked: Effort, thetaMax: number): string {
  const p = reading.probabilities
  const max = p[EFFORTS.length - 1] ?? 0
  const held = picked !== 'max' && p.every((other) => other <= max)
  return readingText(reading, held ? `max is below thetaMax ${thetaMax.toFixed(2)}` : undefined)
}

files.hooks/features/midturn-effort.ts:
// Feature: the main agent's effort, decided again while a turn runs (#5).
//
// Every N steps of a turn, and when the main agent dispatches an agent,
// starts a Workflow or loads a skill, the decision model is asked again how
// much reasoning the rest of the work needs. The question goes out the moment
// a tool call of the main agent starts (`tool.call`), so it is answered while
// the tool runs; the next step (`turn.step`, a layer above the core) takes
// the answer, waits briefly when it is not back yet, and writes the turn's
// plan, which the core then sends. Raising needs thetaUp; lowering needs
// thetaDown, goes one level at a time and waits holdSteps after a raise (a
// forced one too: the escalation feature, #7, marks it in the turn's plan).
//
// The counts the question carries (failed calls, hook blocks) are the
// escalation feature's: one counter for the turn, since the counts last
// started over.
//
// Measured on 2.1.289: the engine runs a step's tool calls while the response
// still streams, so `tool.call` fires inside the step, before the step's
// stream ends. This layer keeps the text of the step as it streams.

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { describeAsked, errorText, within, type Asked } from '../decision/backend.ts'
import { messageText } from '../decision/context.ts'
import { higherEffort, isEffort, readEffort, readingText, type Effort } from '../decision/effort.ts'
import {
  contentLanguage,
  judgeMidturn,
  midturnEffortPart,
  midturnState,
  MIDTURN_LEVEL,
  outcomeOf,
  resultLine,
  toolDetail,
  verdictReason,
  type MidturnCounts,
  type MidturnInput,
  type MidturnLimits,
  type MidturnRules,
  type Outcome,
} from '../decision/midturn.ts'
import { answersFor, mergeParts } from '../decision/system-one.ts'
import { recordDecision } from '../core/decisions.ts'
import { wasBlocked } from '../core/outcomes.ts'
import { floorHeld, MAIN, redecided, turnKey, update, type Cell, type TurnRecord } from '../core/plans.ts'
import type { Ctx } from '../core/setup.ts'
import { failureText, setStatus } from '../core/status.ts'
import { defineSwitch, isOn } from '../core/switches.ts'

const TURNS = { plugin: 'dispatch-pilot', key: 'turns' } as const
const MIDTURN = { plugin: 'dispatch-pilot', key: 'midturn' } as const
const MAIN_STEP = { plugin: 'dispatch-pilot', key: 'mainStep' } as const
const FAILURES = { plugin: 'dispatch-pilot', key: 'escalation', id: MAIN } as const
const LOCK = { plugin: 'dispatch-pilot', key: 'lock' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const

/** The feature's switch (`/dp midturn-effort on|off`). */
const SWITCH = 'midturn-effort'

type ToolEnd = { name: string; detail: string; outcome: Exclude<Outcome, 'running'> }
type StepRecord = { index: number; text: string; tools: ToolEnd[] }
/** The feature's own record of a main turn (`midturn` in types/index.d.ts). */
type MidturnRecord = {
  steps: number
  engine: Effort | null
  askedFor: number | null
  recent: StepRecord[]
}

/** Steps kept in a turn's record. */
const MAX_RECENT = 16

/** Calls that start a new phase of the work (dispatch an agent, start a Workflow, load a skill): each re-decides. */
const PHASE_TOOLS: ReadonlySet<string> = new Set(['Agent', 'Task', 'Workflow', 'Skill'])

/** What the feature runs with: the shared ctx and the options it reads. */
type Settings = {
  ctx: Ctx
  /** Re-decide at every step whose index is a multiple of this; 0 for never. */
  every: number
  rules: MidturnRules
  /** How long a step waits for a re-decision not back yet. */
  waitMs: number
  limits: MidturnLimits
}

/** A step of the main agent: its turn and its index. */
type MainStep = { turnId: string; index: number }
/** A tool call as it starts: its name and what it works on. */
type Starting = { name: string; detail: string }

/**
 * A re-decision on its way: asked for step `forStep` (`reason` says why);
 * `answer` never rejects, and once it resolves `settled` holds it and `ms`
 * how long it took.
 */
type InFlight = { forStep: number; reason: string; answer: Promise<Asked>; settled: Asked | null; ms: number }
/** Re-decisions on their way, by turn key. Promises cannot live in $.state: a reload drops them (the step then keeps its effort). */
const inFlight = new Map<string, InFlight>()
/** The text of the main step streaming now, by turn key. */
const streamed = new Map<string, { index: number; block: number; text: string }>()

export function registerMidturnEffort(on: On, ctx: Ctx): void {
  defineSwitch({ name: SWITCH, info: "re-decides the main agent's effort while a turn runs", segments: ['midturn'] })
  const settings: Settings = { ctx, ...ctx.config.midturn }

  on('tool.call', { tool: /(?:)/ }, async ($, e, next) => {
    // The main agent's own calls only: not a dispatched agent's, nor another plugin's $.tool.call.
    if (e.agentId !== undefined || next.origin.plugin !== 'engine' || !isOn(SWITCH)) return next(e)
    const detail = toolDetail(e)
    let step: MainStep | null = null
    try {
      step = (await $.state.get(MAIN_STEP)).value ?? null
      if (step !== null) await launch($, settings, step, { name: e.tool, detail })
    } catch (error) {
      $.ui.log(`midturn: ${errorText(error)}`, { to: 'debug' })
    }
    const result = await next(e)
    if (step !== null) {
      try {
        const ended: ToolEnd = { name: e.tool, detail, outcome: outcomeOf(e.tool, result, wasBlocked(e.tool_use_id)) }
        const at = step.index
        const ref = { ...MIDTURN, id: turnKey(step.turnId, undefined) }
        const cell: Cell<MidturnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
        await update(cell, (r) => withTool(r ?? newRecord(), at, ended))
      } catch (error) {
        $.ui.log(`midturn: ${errorText(error)}`, { to: 'debug' })
      }
    }
    return result
  })

  on('turn.step', { turnId: /(?:)/ }, async function* ($, e, next) {
    if (e.agentId !== undefined || !isOn(SWITCH)) return yield* next(e)
    const key = turnKey(e.turnId, undefined)
    if (e.index === 0) {
      // A new turn: what is left of earlier turns (a text, an answer never taken) is dropped.
      for (const old of [...streamed.keys()]) if (old !== key) streamed.delete(old)
      for (const old of [...inFlight.keys()]) if (old !== key) inFlight.delete(old)
    }
    try {
      const note = await takeAnswer($, settings, e, key)
      const engine = isEffort(e.effort) ? e.effort : null
      await $.state.set(MAIN_STEP, { turnId: e.turnId, index: e.index })
      const ref = { ...MIDTURN, id: key }
      const cell: Cell<MidturnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
      const record = await update(cell, (r) => ({ ...(r === undefined || e.index === 0 ? newRecord() : r), steps: e.index + 1, engine }))
      const { value: turn } = await $.state.get({ ...TURNS, id: key })
      setStatus('midturn', segment(record, turn, note), (line) => $.ui.status(line))
    } catch (error) {
      $.ui.log(`midturn: ${errorText(error)}`, { to: 'debug' })
    }
    streamed.set(key, { index: e.index, block: -1, text: '' })
    const stream = next(e)
    for await (const chunk of stream) {
      if (chunk.kind === 'text') {
        const live = streamed.get(key)
        if (live !== undefined && live.index === e.index) {
          live.text += live.block !== -1 && live.block !== chunk.index ? `\n${chunk.text}` : chunk.text
          live.block = chunk.index
        }
      }
      yield chunk
    }
    const result = await stream.result
    try {
      const text = messageText(result.answer, settings.limits.tokens)
      const ref = { ...MIDTURN, id: key }
      const cell: Cell<MidturnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
      await update(cell, (r) => withText(r ?? newRecord(), e.index, text))
    } catch (error) {
      $.ui.log(`midturn: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })
}

/**
 * Asks again about the turn's effort, for the step after `step`, when a call
 * starting is a reason to: a phase tool, or a step index that is a multiple of
 * `every`. Once per step; the answer is left for that step to take.
 */
async function launch($: EngineInterface, s: Settings, step: MainStep, starting: Starting): Promise<void> {
  const upcoming = step.index + 1
  const key = turnKey(step.turnId, undefined)
  const [{ value: turn }, { value: record }, { value: lock = null }, { value: failures }, sentAt] = await Promise.all([
    $.state.get({ ...TURNS, id: key }),
    $.state.get({ ...MIDTURN, id: key }),
    $.state.get(LOCK),
    $.state.get(FAILURES),
    $.clock.now(),
  ])
  // Only a turn the person's own message started is re-decided, whether its start was decided or not (that request
  // may have failed: then from the session's own effort); never without a decision model set up (every request would
  // fail at once).
  if (turn === undefined || turn.person !== true || lock !== null || record === undefined || record.engine === null || s.ctx.backend.configured === false) return
  const reason = PHASE_TOOLS.has(starting.name) ? starting.name : s.every > 0 && upcoming % s.every === 0 ? `every ${s.every} steps` : null
  if (reason === null || record.askedFor === upcoming || inFlight.get(key)?.forStep === upcoming) return
  const input: MidturnInput = {
    message: turn.prompt,
    step: upcoming,
    current_effort: higherEffort(turn.effort ?? record.engine, floorHeld(turn, upcoming)) as Effort,
    counts: countsOf(turn, step.turnId, failures),
    recent_steps: summaries(record, step.index, key, starting, contentLanguage(turn.prompt)),
  }
  const request = mergeParts(midturnState(input, s.limits), [midturnEffortPart(s.ctx.ask)])
  const io = {
    fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
    sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
  }
  const asking = s.ctx.backend.ask(io, request, s.ctx.config.timeoutMs)
  const entry: InFlight = { forStep: upcoming, reason, answer: asking, settled: null, ms: 0 }
  entry.answer = asking.then(async (answered) => {
    entry.ms = (await $.clock.now()) - sentAt
    entry.settled = answered
    return answered
  })
  inFlight.set(key, entry)
  const ref = { ...MIDTURN, id: key }
  const cell: Cell<MidturnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
  await update(cell, (r) => ({ ...(r ?? newRecord()), askedFor: upcoming }))
}

/**
 * The turn's counts as the decision model reads them: its decisions and level
 * changes, and the failed calls and hook blocks the escalation feature counted
 * for it, since its counts last started over (a forced raise, or failures
 * found expected).
 */
function countsOf(turn: TurnRecord, turnId: string, failures: { turnId: string; failures: number; hookBlocks: number; base: { failures: number; hookBlocks: number } } | undefined): MidturnCounts {
  const counted = failures !== undefined && failures.turnId === turnId
  return {
    judgments: turn.decisions,
    changes: turn.changes,
    failures: counted ? failures.failures - failures.base.failures : 0,
    hook_blocks: counted ? failures.hookBlocks - failures.base.hookBlocks : 0,
  }
}

/**
 * Takes the re-decision meant for this step, if any, and writes what it
 * decides into the turn's plan. An answer not back yet gets `waitMs` more;
 * still none, the step keeps the effort it had and the answer stays for a
 * later step. Resolves to what the status line should add: `late`, or why
 * there is no answer; null otherwise.
 */
async function takeAnswer($: EngineInterface, s: Settings, e: { index: number; effort?: unknown }, key: string): Promise<string | null> {
  const pending = inFlight.get(key)
  if (pending === undefined || pending.forStep > e.index) return null
  let asked = pending.settled
  if (asked === null) {
    asked = await within((ms, signal) => $.clock.sleep(ms, { signal }), pending.answer, s.waitMs, null)
  }
  if (asked === null) return 'late'
  inFlight.delete(key)
  $.ui.log(`request [midturn.${MIDTURN_LEVEL}] for step ${pending.forStep} (${pending.reason}) to ${s.ctx.backend.name}: ${describeAsked(asked, pending.ms)}`, { to: 'debug' })
  const engine = isEffort(e.effort) ? e.effort : null
  const [{ value: turn }, { value: lock = null }] = await Promise.all([$.state.get({ ...TURNS, id: key }), $.state.get(LOCK)])
  if (turn === undefined || lock !== null || engine === null) return null
  const floor = floorHeld(turn, e.index)
  const current = higherEffort(turn.effort ?? engine, floor) as Effort
  const reading = asked.ok ? readEffort(answersFor(midturnEffortPart(s.ctx.ask), asked.answers)[MIDTURN_LEVEL]) : null
  if (reading === null) return asked.ok ? failureText(s.ctx.backend.name, { kind: 'parse', detail: 'no effort answer' }) : failureText(s.ctx.backend.name, asked.failure)

  const ref = { ...TURNS, id: key }
  const turnCell: Cell<TurnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
  const sinceRaise = turn.raisedAt == null ? null : e.index - turn.raisedAt
  const position = { current, sinceRaise, atLeast: floor }
  const verdict = judgeMidturn(reading, position, s.rules)
  await update(turnCell, (r) => redecided(r ?? turn, current, verdict.effort, e.index))
  await recordDecision({ get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) }, (line) => $.ui.log(line, { to: 'debug' }), {
    feature: SWITCH,
    outcome: `effort ${verdict.effort} ${verdict.effort === current ? '(kept)' : `(was ${current})`}`,
    about: `step ${e.index} (${pending.reason})`,
    reason: `${readingText(reading)}; ${verdictReason(verdict, position, s.rules)}`,
  })
  return null
}

/**
 * The feature's status segment: how many steps the turn has made, how many
 * decisions and level changes it had, once it has been re-decided (so a
 * short turn stays quiet); none at a turn's first step.
 */
function segment(record: MidturnRecord, turn: TurnRecord | undefined, note: string | null): string | null {
  if (record.askedFor === null || turn === undefined) return null
  return `steps ${record.steps}, judged ${turn.decisions}, changed ${turn.changes}${note === null ? '' : ` (${note})`}`
}

function newRecord(): MidturnRecord {
  return { steps: 0, engine: null, askedFor: null, recent: [] }
}

/**
 * The latest steps as the decision model reads them, oldest first: each
 * step's text and its tool calls with how they ended. Step `index` comes
 * last, its text as streamed so far, the call `starting` in it marked running.
 */
function summaries(record: MidturnRecord, index: number, key: string, starting: Starting, language: 'en' | 'zh'): MidturnInput['recent_steps'] {
  const live = streamed.get(key)
  const now = record.recent.find((step) => step.index === index)
  const line = (t: { name: string; detail: string; outcome: Outcome }) => ({ name: t.name, result: resultLine(t.outcome, t.detail, language) })
  return [
    ...record.recent.filter((step) => step.index < index).map((step) => ({ assistant_text: step.text, tools: step.tools.map(line) })),
    {
      assistant_text: live?.index === index ? live.text : (now?.text ?? ''),
      tools: [...(now?.tools ?? []).map(line), line({ ...starting, outcome: 'running' })],
    },
  ]
}

/** The record with a tool call's ending added to its step. */
function withTool(record: MidturnRecord, index: number, ended: ToolEnd): MidturnRecord {
  const at = record.recent.findIndex((step) => step.index === index)
  const step = at >= 0 ? (record.recent[at] as StepRecord) : { index, text: '', tools: [] }
  const recent = [...record.recent]
  if (at >= 0) recent[at] = { ...step, tools: [...step.tools, ended] }
  else recent.push({ ...step, tools: [ended] })
  return { ...record, recent: recent.sort((a, b) => a.index - b.index).slice(-MAX_RECENT) }
}

/** The record with a step's text, once the step has streamed whole. */
function withText(record: MidturnRecord, index: number, text: string): MidturnRecord {
  const at = record.recent.findIndex((step) => step.index === index)
  const recent = [...record.recent]
  if (at >= 0) recent[at] = { ...(recent[at] as StepRecord), text }
  else recent.push({ index, text, tools: [] })
  return { ...record, recent: recent.sort((a, b) => a.index - b.index).slice(-MAX_RECENT) }
}

