// Masks common secret formats before any text leaves for the decision model
// (spec: "发送前对 secret 脱敏"). Best effort: known token prefixes, credential
// assignments, URL passwords, private keys. Pure (see system-one.ts).

const MASK = '[REDACTED]'

/** Names whose `name = value` / `name: value` value is a secret. */
const NAME = String.raw`[A-Za-z0-9_.-]*(?:password|passwd|pwd|secret|token|api[_-]?key|apikey|access[_-]?key|private[_-]?key|credential)[A-Za-z0-9_.-]*`

const PATTERNS: readonly (readonly [RegExp, string])[] = [
  // A PEM private key, whole.
  [/-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z0-9 ]*PRIVATE KEY-----/g, '[REDACTED PRIVATE KEY]'],
  // Provider keys by their prefixes.
  [/\b(?:sk|rk|pk)-(?:ant-|proj-|live-|test-)?[A-Za-z0-9_-]{16,}/g, MASK], // Anthropic, OpenAI and alike
  [/\b(?:sk|rk|pk)_(?:live|test)_[A-Za-z0-9]{16,}/g, MASK], // Stripe
  [/\bgh[pousr]_[A-Za-z0-9]{30,}/g, MASK], // GitHub
  [/\bgithub_pat_[A-Za-z0-9_]{40,}/g, MASK],
  [/\bglpat-[A-Za-z0-9_-]{20,}/g, MASK], // GitLab
  [/\bxox[abposr]-[A-Za-z0-9-]{10,}/g, MASK], // Slack
  [/\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g, MASK], // AWS access key id
  [/\bAIza[0-9A-Za-z_-]{35}/g, MASK], // Google API key
  [/\bnpm_[A-Za-z0-9]{36}\b/g, MASK], // npm
  [/\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g, MASK], // JWT
  // Bearer and Basic credentials.
  [/\b(Bearer|Basic)\s+[A-Za-z0-9._~+/=-]{16,}/g, `$1 ${MASK}`],
  // The password of a URL: scheme://user:password@host.
  [/(\b[a-z][a-z0-9+.-]*:\/\/[^\s:/@]+:)[^\s@/]+@/gi, `$1${MASK}@`],
  // name = "value" and name = value.
  [new RegExp(String.raw`\b(${NAME})(\s*[:=]\s*)(["'])[^"'\n]{4,}\3`, 'gi'), `$1$2$3${MASK}$3`],
  [new RegExp(String.raw`\b(${NAME})(\s*[:=]\s*)(?!\[REDACTED)[^\s"',;]{6,}`, 'gi'), `$1$2${MASK}`],
  // 密码是 xxx, 密钥：xxx
  [/(密码|口令|密钥|秘钥|令牌)(\s*(?:[:：=]|是|为)\s*)[^\s，。,;；]{4,}/g, `$1$2${MASK}`],
]

export function redactSecrets(text: string): string {
  let out = text
  for (const [pattern, replacement] of PATTERNS) out = out.replace(pattern, replacement)
  return out
}

/** The start of a text as the decision log quotes it: secrets masked, whitespace collapsed, cut at 40 characters, in quotes. */
export function quoteStart(text: string): string {
  const flat = redactSecrets(text).replace(/\s+/g, ' ').trim()
  return JSON.stringify(flat.length > 40 ? `${flat.slice(0, 40)}...` : flat)
}

files.hooks/decision/workflow-labels.ts:
// The Workflow fallback (#9): which `agent()` call of a script an agent of a
// running Workflow stands for, found by the label the engine recorded for it,
// and what to set on that agent's steps.
//
// A Workflow's agents never pass `agent.spawn`, and the workflow-agents
// feature (#8) can write their model and effort into the script only when the
// script is inline and it can read the call. For the rest (a script given by
// path or by name, a resumed run, a script it cannot read, a call whose prompt
// is data), the model and effort are set on each agent's own steps: the run's
// journal says which label each agent started under, the label says which call
// it is, and the call's decision (made when the run started, or from the
// agent's own prompt when it starts) goes into the plan table.
//
// Pure (see system-one.ts).

import type { Failure } from './backend.ts'
import { modelFamily, termsOf, type AgentModel, type Terms } from './dispatched-agent.ts'
import type { Effort } from './effort.ts'
import { modelId } from './model-ids.ts'
import type { AgentCall, Written } from './workflow-script.ts'
import { callName, outcomeOf, whyOf, type CallOutcome, type Skipped } from './workflow.ts'

/** How the agents of one call are routed. */
export type SiteRoute =
  /** Decided when the run started: what each of its agents is set to (null: the step's own). */
  | { kind: 'set'; model: AgentModel | null; effort: Effort | null }
  /** Decided when each of its agents starts, from that agent's own prompt. */
  | { kind: 'runtime' }
  /** Left to the script: the workflow-agents feature wrote it, it already says what was decided, or no decision was made. */
  | { kind: 'script' }

/** How a label the journal recorded is told to be a call's. */
export type LabelMatch =
  /** A label the script writes as a string: that string. */
  | { kind: 'exact'; label: string }
  /** A template label: a regular expression's source, its `${...}` matching anything. */
  | { kind: 'pattern'; source: string }
  /** No label: the engine records the prompt's start; `whole` when the prompt is a string, not a template. */
  | { kind: 'head'; head: string; whole: boolean }
  /** Nothing to tell it by: a label, or a prompt without one, that the script works out when it runs. */
  | { kind: 'none' }

/** One `agent()` call of a run's script, as the fallback keeps it (`labelRuns` in types/index.d.ts). */
export type RunSite = {
  /** The line it starts on, for the log. */
  line: number
  /** The label as written (a template keeps its `${...}`); null when there is none or it is worked out when the script runs. */
  label: string | null
  match: LabelMatch
  route: SiteRoute
  /** The call's own options, for a decision made as its agents start (what the script works out itself is left alone). */
  model: Written
  effort: Written
  agentType: string | null
  /** The person's terms for the call's work, as its decision read them (null: none, or not decided yet); its agents' plans keep them. */
  terms: Terms | null
}

/** The routes of a script's calls, from what was decided about them when the run started (`readOutcomes`). */
export function sitesOf(calls: readonly AgentCall[], outcomes: readonly CallOutcome[]): RunSite[] {
  return calls.map((call, index) => {
    const outcome = outcomes[index]
    return siteOf(call, routeOf(outcome), outcome === undefined || outcome.kind === 'left' ? null : termsOf(outcome.decision))
  })
}

/**
 * The routes of the calls of a script the main agent sent inline: the
 * workflow-agents feature asked about every call but those in `skipped` (a
 * prompt it cannot read, a call past what it asks about), and wrote what it
 * could into the script; those are decided as their agents start. `terms`:
 * what its decisions read of the person's terms for each call, by index.
 */
export function inlineSites(calls: readonly AgentCall[], skipped: readonly Skipped[], terms: readonly (Terms | null)[] = []): RunSite[] {
  const left = new Set(skipped.map((skip) => skip.index))
  return calls.map((call) => siteOf(call, left.has(call.index) ? { kind: 'runtime' } : { kind: 'script' }, terms[call.index] ?? null))
}

function siteOf(call: AgentCall, route: SiteRoute, terms: Terms | null): RunSite {
  return { line: call.line, label: call.label, match: matchOf(call), route, model: call.model, effort: call.effort, agentType: call.agentType, terms }
}

function routeOf(outcome: CallOutcome | undefined): SiteRoute {
  if (outcome === undefined || outcome.kind === 'kept') return { kind: 'script' }
  if (outcome.kind === 'left') return outcome.reason === 'unreadable' || outcome.reason === 'capped' ? { kind: 'runtime' } : { kind: 'script' }
  const model = (outcome.write.model ?? null) as AgentModel | null
  const effort = typeof outcome.write.effort === 'string' ? (outcome.write.effort as Effort) : null
  return { kind: 'set', model, effort }
}

/**
 * How the label the engine records for one of the call's agents is told to be
 * this call's. A label the script writes as a string is that string. A
 * template label (`migrate:${file}`, read as written: the parser keeps its
 * `${...}`) is a pattern: its own text must be there, each placeholder matches
 * anything; one with no text of its own says nothing. A call without a label
 * is recorded under the start of its prompt (measured on 2.1.289: whitespace
 * collapsed, cut at 60 characters): a string prompt's start, or a template's
 * own text before its first placeholder.
 */
function matchOf(call: AgentCall): LabelMatch {
  if (call.labelKind === 'string' && call.label !== null) return { kind: 'exact', label: call.label }
  if (call.labelKind === 'template' && call.label !== null) {
    const pieces = templatePieces(call.label)
    if (pieces.every((piece) => piece.placeholder || piece.text.trim() === '')) return { kind: 'none' }
    const source = pieces.map((piece) => (piece.placeholder ? '[\\s\\S]*' : escapeRegExp(cooked(piece.text)))).join('')
    return { kind: 'pattern', source: `^${source}$` }
  }
  if (call.labelKind === 'none' && call.prompt !== null) {
    const pieces = call.prompt.includes('${') ? templatePieces(call.prompt) : [{ text: call.prompt, placeholder: false }]
    const first = pieces[0]
    const whole = pieces.length === 1 && first?.placeholder === false
    // A string prompt is already cooked; a template's text is as written.
    const head = first === undefined || first.placeholder ? '' : flat(whole ? first.text : cooked(first.text))
    return head === '' ? { kind: 'none' } : { kind: 'head', head: whole ? head.slice(0, ENGINE_LABEL) : head, whole }
  }
  return { kind: 'none' }
}

/** How many characters of a prompt the engine records as the label of a call without one. */
const ENGINE_LABEL = 60

/** Text with each run of whitespace one space, trimmed: how a label and a prompt's start compare. */
function flat(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

/** Whether `label` is what the engine records for a call without one whose prompt starts as `match` says. */
function startsAs(label: string, match: { head: string; whole: boolean }): boolean {
  const recorded = flat(label)
  if (match.whole || match.head.length >= ENGINE_LABEL) return recorded === flat(match.head.slice(0, ENGINE_LABEL))
  return recorded.startsWith(match.head)
}

/** A template's text as written, cut into its own text and its `${...}` (braces counted, so a placeholder holding an object goes whole). */
function templatePieces(template: string): { text: string; placeholder: boolean }[] {
  const pieces: { text: string; placeholder: boolean }[] = []
  let text = ''
  let i = 0
  while (i < template.length) {
    if (template.charAt(i) === '\\') {
      text += template.slice(i, i + 2)
      i += 2
    } else if (template.charAt(i) === '$' && template.charAt(i + 1) === '{') {
      let depth = 1
      let end = i + 2
      while (end < template.length && depth > 0) {
        if (template.charAt(end) === '{') depth++
        else if (template.charAt(end) === '}') depth--
        end++
      }
      if (text !== '') pieces.push({ text, placeholder: false })
      pieces.push({ text: template.slice(i, end), placeholder: true })
      text = ''
      i = end
    } else {
      text += template.charAt(i)
      i++
    }
  }
  if (text !== '') pieces.push({ text, placeholder: false })
  return pieces
}

const ESCAPES: Record<string, string> = { n: '\n', t: '\t', r: '\r', b: '\b', f: '\f', v: '\v', '0': '\0' }

/** A template's own text as the script's value has it: its escapes worked out. */
function cooked(raw: string): string {
  return raw.replace(/\\(?:u\{([0-9a-fA-F]+)\}|u([0-9a-fA-F]{4})|x([0-9a-fA-F]{2})|(\r\n|[\s\S]))/g, (_, braced?: string, unicode?: string, hex?: string, plain?: string) => {
    const code = braced ?? unicode ?? hex
    if (code !== undefined) return String.fromCodePoint(Number.parseInt(code, 16))
    if (plain === '\n' || plain === '\r\n') return ''
    return ESCAPES[plain as string] ?? (plain as string)
  })
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/** What the engine's journal says of one agent: the label it started under. */
export type JournalStart = { label: string; phase: string | null }

/** The `started` line of `agentId` in a run's journal (`journal.jsonl`); null when the agent is not in it (yet). */
export function startedIn(journal: string, agentId: string): JournalStart | null {
  for (const line of journal.split('\n')) {
    if (!line.includes(agentId)) continue
    try {
      const row = JSON.parse(line) as { type?: unknown; agentId?: unknown; label?: unknown; phase?: unknown }
      if (row.type === 'started' && row.agentId === agentId && typeof row.label === 'string') {
        return { label: row.label, phase: typeof row.phase === 'string' ? row.phase : null }
      }
    } catch {
      // a line being written: not this agent's
    }
  }
  return null
}

/**
 * The calls of `sites` an agent the journal recorded under `label` can be
 * one of: the calls whose string label it is; else those whose template it
 * fits; else, when none does, the calls nothing tells apart (a label or prompt
 * the script works out when it runs).
 */
export function sitesFor(label: string, sites: readonly RunSite[]): RunSite[] {
  const exact = sites.filter((site) => site.match.kind === 'exact' && site.match.label === label)
  if (exact.length > 0) return exact
  const fits = sites.filter((site) => (site.match.kind === 'pattern' && new RegExp(site.match.source).test(label)) || (site.match.kind === 'head' && startsAs(label, site.match)))
  if (fits.length > 0) return fits
  return sites.filter((site) => site.match.kind === 'none')
}

/** What the engine writes before a workflow agent's task, up to the task itself (2.1.289); each line of the task follows indented by two spaces. */
const TASK_FOLLOWS = 'The computed task text follows:\n'
/** How the frame starts in which the engine relays the person's request to a workflow agent, before its task (seen on 2.1.281-2.1.282). */
const RELAYED_REQUEST = '[Workflow harness — user request]'

/** The task a script computed, without the frame the engine puts around it; null when `text` is not such a frame. */
export function computedTask(text: string): string | null {
  const at = text.indexOf(TASK_FOLLOWS)
  if (at < 0) return null
  return text
    .slice(at + TASK_FOLLOWS.length)
    .split('\n')
    .map((taskLine) => (taskLine.startsWith('  ') ? taskLine.slice(2) : taskLine))
    .join('\n')
}

/** Whether `text` is the frame in which the engine relays the person's request to a workflow agent (not the agent's task). */
export function isRelayedRequest(text: string): boolean {
  return text.trimStart().startsWith(RELAYED_REQUEST)
}

/**
 * The task a workflow agent was given, from its transcript
 * (`agent-<agentId>.jsonl`): the first user message (past one that relays
 * the person's request, as some engines write first), without the frame the
 * engine puts around a task a script computed. Null when the transcript holds
 * no such message (yet).
 */
export function taskOf(transcript: string): string | null {
  for (const line of transcript.split('\n')) {
    let row: { type?: unknown; message?: { role?: unknown; content?: unknown } }
    try {
      row = JSON.parse(line) as typeof row
    } catch {
      continue
    }
    if (row.type !== 'user' || row.message?.role !== 'user') continue
    const content = row.message.content
    const text = typeof content === 'string' ? content : Array.isArray(content) ? content.map((block: { text?: unknown }) => (typeof block?.text === 'string' ? block.text : '')).join('') : ''
    if (isRelayedRequest(text)) continue
    return computedTask(text) ?? (text.trim() === '' ? null : text)
  }
  return null
}

/** Whether `label` is only what the engine records for an agent of a call without a label: the start of its task. */
export function isTaskStart(label: string, task: string): boolean {
  const recorded = flat(label)
  return recorded !== '' && flat(flat(task).slice(0, ENGINE_LABEL)) === recorded
}

/** What one agent's steps go out with: a model id when it changes the step's family (null keeps the step's own), and the effort. */
export function agentPlan(route: { model: AgentModel | null; effort: Effort | null }, stepModel: string): { model: string | null; effort: Effort | null } {
  const model = route.model !== null && route.model !== modelFamily(stepModel) ? modelId(route.model) : null
  return { model, effort: route.effort }
}

/** How the Workflow tool was handed the script: inline (`script`), by `scriptPath`, by `name`, or inline to resume an earlier run. */
export type Given = 'script' | 'path' | 'name' | 'resume'

/**
 * What the main agent reads after the Workflow tool's result about the agents
 * this feature routes as they start; null when there is nothing to say.
 * `launched`: what was decided about each call when the run started (a
 * script given by path or by name, or resumed).
 */
export function launchNote(
  given: Given,
  sites: readonly RunSite[] | null,
  launched: { calls: readonly AgentCall[]; outcomes: readonly CallOutcome[]; describe: (failure: Failure) => string } | null,
): string | null {
  if (sites === null) return "Dispatch Pilot (the user's routing plugin) could not read this script, so it decides each agent's model and effort as the agent starts, from its label and its task."
  if (given === 'script') {
    return sites.some((site) => site.route.kind === 'runtime')
      ? "Dispatch Pilot (the user's routing plugin) sets the model and effort of the agents of the agent() calls it leaves as written, as each one starts, from its label and its task."
      : null
  }
  if (launched === null) return null
  const lines = launched.outcomes.map((outcome, index) => {
    const call = launched.calls[index] as AgentCall
    if (outcome.kind === 'written') {
      const why = whyOf(outcome.decision)
      return `- ${callName(call)}: ${outcomeOf(call, outcome.decision)}${why === '' ? '' : ` (${why})`}`
    }
    if (outcome.kind === 'kept') return `- ${callName(call)}: as the script has it (${outcomeOf(call, outcome.decision)})`
    if (outcome.reason === 'unreadable' || outcome.reason === 'capped') return `- ${callName(call)}: decided as each of its agents starts, from its label and its task`
    return `- ${callName(call)}: as the script has it (${outcome.failure === undefined ? 'no answer from the decision model' : launched.describe(outcome.failure)})`
  })
  const header = launched.outcomes.some((outcome) => outcome.kind !== 'left')
    ? "Dispatch Pilot (the user's routing plugin) chose a model and an effort for the agent() calls of this Workflow. The script is unchanged: each agent gets its call's choice as it starts, found by its label."
    : "Dispatch Pilot (the user's routing plugin) decides the model and effort of this Workflow's agents as each one starts. The script is unchanged."
  return [header, ...lines].join('\n')
}

/** The person's terms every one of `sites` carries; null when they carry none, or not the same. */
export function sharedTerms(sites: readonly RunSite[]): Terms | null {
  const first = sites[0]?.terms ?? null
  return first !== null && sites.every((site) => JSON.stringify(site.terms) === JSON.stringify(first)) ? first : null
}

/** Whether two routes set the same thing. */
export function sameRoute(a: SiteRoute, b: SiteRoute): boolean {
  if (a.kind !== b.kind) return false
  return a.kind !== 'set' || b.kind !== 'set' || (a.model === b.model && a.effort === b.effort)
}

files.hooks/core/profiles.ts:
// Skill profiles (#11): what each skill is for, in English and in Chinese,
// written once per version of its SKILL.md by a cheap model through
// `$.model.complete` and kept in `$.store`, so that a request in Chinese can
// match a skill its author described in English. The ranking offers a skill by
// its profile when one is written, else by its description
// (decision/skills.ts).
//
// Pure: no `$`. The skills feature runs the completions and reads and writes
// the store; this module writes the prompt, reads the reply, names each
// profile's store key (from the SKILL.md, so an edited file gets a new one)
// and keeps the profiles within their share of the store's 4 MiB.

import { clipToTokens } from '../decision/context.ts'
import { redactSecrets } from '../decision/redact.ts'
import type { SkillProfile } from '../decision/skills.ts'
import { loadCatalog, type CatalogIo, type CatalogSkill } from './skills.ts'

/** Bumped when the prompt changes: every profile is written again. */
export const PROFILE_VERSION = 1
/** A profile's store key is this prefix and a hash of what it was written from. */
export const PROFILE_PREFIX = 'profile.'
/** How much of a SKILL.md the model reads: its start, where a skill says what it is for. */
export const SOURCE_TOKENS = 3000
/** The reply's cap, and how long one completion may take. */
export const PROFILE_MAX_TOKENS = 700
export const PROFILE_TIMEOUT_MS = 60_000
/** A field longer than this (characters) is cut: English, Chinese. */
export const EN_CHARS = 200
export const ZH_CHARS = 60
/**
 * The store keeps at most this many profiles; past it the oldest written that
 * the session does not use go, down to EVICT_TO. At most about 1.3 KB each
 * (the field caps), so they take well under 1 MiB of the store's 4 MiB.
 */
export const MAX_PROFILES = 500
export const EVICT_TO = 400
/**
 * And at most this many bytes of them (key and JSON value), whatever their
 * count: entries another version wrote may be bigger. Past it the oldest go
 * the same way, down to EVICT_TO_BYTES. Half the store's 4 MiB, the rest left
 * to the mod's other keys.
 */
export const MAX_PROFILE_BYTES = 2 * 1024 * 1024
export const EVICT_TO_BYTES = 1.5 * 1024 * 1024

export const PROFILE_SYSTEM =
  'You write short routing profiles of Claude Code skills. A router that reads requests written in Chinese or English uses them to decide whether a skill fits a request. Reply with one JSON object and nothing else.'

/** What the model is asked for one skill: its name, its description and the start of its SKILL.md (null when it has none to read). */
export function profilePrompt(skill: { name: string; description: string }, markdown: string | null): string {
  const source =
    markdown === null
      ? 'SKILL.md: not available; work from the name and the description.'
      : `SKILL.md (it may be cut short):\n<<<\n${clipToTokens(markdown.trim(), SOURCE_TOKENS)}\n>>>`
  return [
    `Skill name: ${skill.name}`,
    `Description: ${skill.description.trim() || '(none)'}`,
    source,
    '',
    "Write this skill's profile as JSON with exactly these fields:",
    '{"en": {"what": "...", "use_when": "...", "not_for": "..."}, "zh": {"what": "...", "use_when": "...", "not_for": "..."}}',
    '- en.what: what the skill does, in one sentence of at most 20 words.',
    '- en.use_when: the requests or situations it is for, in at most 25 words.',
    '- en.not_for: nearby requests it does not cover, in at most 20 words.',
    '- zh.what, zh.use_when, zh.not_for: the same three in natural Chinese (not a word-for-word translation), at most 40 characters each.',
    'Say only what the skill itself says it does; do not invent features. Plain text in the strings, no markdown.',
  ].join('\n')
}

/** The profile in the model's reply (the JSON object in it); null when there is none or a field is missing. Every field is tidied and cut to its cap. */
export function readProfile(reply: string): SkillProfile | null {
  const start = reply.indexOf('{')
  const end = reply.lastIndexOf('}')
  if (start < 0 || end <= start) return null
  try {
    return profileFrom(JSON.parse(reply.slice(start, end + 1)))
  } catch {
    return null
  }
}

/** A profile as the store keeps it: whose it is (for the log), when it was written, and the profile. */
export type StoredProfile = { name: string; at: number; profile: SkillProfile }

/** The profile a store value holds; null when it holds none (missing, or not a profile). */
export function storedProfile(value: unknown): SkillProfile | null {
  return isRecord(value) ? profileFrom(value.profile) : null
}

/**
 * The store key of a skill's profile: a hash of what it is written from (its
 * SKILL.md, or its description when it has none), its name, the model and
 * PROFILE_VERSION. A changed file, another model or a new prompt gets a new
 * key, so its profile is written again. Synchronous (two 53-bit hashes, not
 * `crypto.subtle`), so it is computed in line with the code around it.
 */
export function profileKey(skill: { name: string; description: string }, markdown: string | null, model: string): string {
  const source = ['dispatch-pilot skill profile', String(PROFILE_VERSION), model, skill.name, markdown ?? `description: ${skill.description.trim()}`].join('\n')
  return `${PROFILE_PREFIX}${hash53(source, 1)}${hash53(source, 2)}`
}

/** cyrb53 (bryc, public domain): a 53-bit hash of `text` as 14 hex digits; another `seed` gives an independent one. */
function hash53(text: string, seed: number): string {
  let h1 = 0xdeadbeef ^ seed
  let h2 = 0x41c6ce57 ^ seed
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i)
    h1 = Math.imul(h1 ^ code, 2654435761)
    h2 = Math.imul(h2 ^ code, 1597334677)
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507)
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909)
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507)
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909)
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0')
}

/** What looking up the profiles needs of the session, as closures over `$`. */
export type ProfileIo = {
  /** `$.fs.read(path)`. */
  read: (path: string) => Promise<string>
  /** `$.store.get(key)`: rejects when the store cannot be read. */
  get: (key: string) => Promise<unknown>
}

/**
 * The catalog with each skill's profile key and, when the store holds it, its
 * profile. `store` is false when the store cannot be read: then no profile is
 * found, and none should be written (it could not be kept).
 */
export async function lookUpProfiles(skills: readonly CatalogSkill[], io: ProfileIo, model: string): Promise<{ skills: CatalogSkill[]; store: boolean }> {
  let store = true
  const found = await Promise.all(
    skills.map(async (skill): Promise<CatalogSkill> => {
      const markdown = skill.file === null ? null : await io.read(skill.file).catch(() => null)
      const key = profileKey(skill, markdown, model)
      const value = await io.get(key).catch(() => {
        store = false
        return undefined
      })
      return { ...skill, profileKey: key, profile: storedProfile(value) }
    }),
  )
  return { skills: store ? found : found.map((skill) => ({ ...skill, profile: null })), store }
}

/**
 * The session's skills (`loadCatalog`), each with its profile when the store
 * holds one (`lookUpProfiles`): what both the skills feature and find_skill
 * keep as the session's catalog. Null when the skills cannot be read.
 */
export async function readSessionSkills(io: CatalogIo & Pick<ProfileIo, 'get'>, model: string): Promise<{ skills: CatalogSkill[]; store: boolean } | null> {
  const skills = await loadCatalog(io).catch(() => null)
  return skills === null ? null : lookUpProfiles(skills, io, model)
}

/** The catalog with `profile` given to the skills whose profile key is `key`. */
export function withProfile(skills: readonly CatalogSkill[], key: string, profile: SkillProfile): CatalogSkill[] {
  return skills.map((skill) => (skill.profileKey === key ? { ...skill, profile } : skill))
}

/** A stored profile as eviction weighs it: its key, when it was written, its size in bytes (`storedBytes`). */
export type StoredEntry = { key: string; at: number; bytes: number }

/** What a store entry takes: its key and its value as JSON, in UTF-8 bytes. */
export function storedBytes(key: string, value: unknown): number {
  return new TextEncoder().encode(key + (JSON.stringify(value) ?? '')).length
}

/**
 * The profiles to drop from the store: none while it holds at most
 * MAX_PROFILES of them and MAX_PROFILE_BYTES; past either, the oldest written
 * among those not in `keep` (the session's), until at most EVICT_TO remain and
 * they take at most EVICT_TO_BYTES.
 */
export function evictions(entries: readonly StoredEntry[], keep: ReadonlySet<string>): string[] {
  let count = entries.length
  let bytes = entries.reduce((sum, entry) => sum + entry.bytes, 0)
  if (count <= MAX_PROFILES && bytes <= MAX_PROFILE_BYTES) return []
  const drop: string[] = []
  for (const entry of entries.filter((one) => !keep.has(one.key)).sort((a, b) => a.at - b.at)) {
    if (count <= EVICT_TO && bytes <= EVICT_TO_BYTES) break
    drop.push(entry.key)
    count--
    bytes -= entry.bytes
  }
  return drop
}

function profileFrom(value: unknown): SkillProfile | null {
  if (!isRecord(value) || !isRecord(value.en) || !isRecord(value.zh)) return null
  const en = side(value.en, EN_CHARS)
  const zh = side(value.zh, ZH_CHARS)
  return en === null || zh === null ? null : { en, zh }
}

/** One language's fields: `what` and `use_when` must be there; `not_for` may be empty. */
function side(value: Record<string, unknown>, max: number): SkillProfile['en'] | null {
  const read = (field: string) => {
    const text = value[field]
    return typeof text === 'string' ? tidy(text, max) : null
  }
  const what = read('what')
  const useWhen = read('use_when')
  const notFor = read('not_for') ?? ''
  return what && useWhen ? { what, use_when: useWhen, not_for: notFor } : null
}

/** A field as the decision model reads it: secrets masked, whitespace collapsed, cut to `max` characters. */
function tidy(text: string, max: number): string {
  const chars = [...redactSecrets(text).replace(/\s+/g, ' ').trim()]
  return chars.length > max ? `${chars.slice(0, max - 1).join('').trimEnd()}…` : chars.join('')
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

