// The skill catalog: which skills the session has, who may start each one,
// and what each is for. The skills feature (#10) suggests from it, the
// find_skill tool (#12) answers from it, and its bilingual profiles (#11,
// core/profiles.ts) are written for it. Also the engine's skill listing, read
// and trimmed, and how the ranking is described and set up.
//
// Pure: no `$`. Whatever reads the session (commands, settings, disk) comes
// in as closures the hook that owns `$` builds (DEVELOPMENT.md, 开发).

import type { Language } from '../decision/effort.ts'
import { questionBudget, SHORTLIST_FLOOR, type RankerSettings, type SkillOption, type SkillRanking, type SkillShare } from '../decision/skills.ts'
import type { Config } from './setup.ts'

/**
 * What the two stages of a ranking said, for a decision's reason: the skills
 * the main agent can load that stage one put forward with their shares, and
 * none's (`first`); the same of its question on the skills only the person
 * can start, when it was asked (`hint`); how well each fits by stage two, or
 * that stage one put none forward.
 */
export function describeStages(ranking: SkillRanking): string {
  const shares = (shortlist: readonly SkillShare[], none: number) => [...shortlist.map((entry) => `${entry.name} ${entry.share.toFixed(2)}`), `none ${none.toFixed(2)}`].join(', ')
  const shortlist = ranking.shortlist ?? []
  const hint = ranking.hints === undefined ? '' : `; hint ${shares(ranking.hints.shortlist, ranking.hints.none)}`
  const second =
    shortlist.length + (ranking.hints?.shortlist.length ?? 0) === 0
      ? `no skill rated ${SHORTLIST_FLOOR.toFixed(2)} or more`
      : `fits ${ranking.ranked.map((entry) => `${entry.name} ${entry.relevance.toFixed(2)}`).join(', ')}`
  return `first ${shares(shortlist, ranking.none)}${hint}; ${second}`
}

/**
 * How skills are ranked (`modRanker`'s settings), from the person's options
 * (core/setup.ts), the same wherever skills are ranked: the message's
 * suggestions and find_skill (#12). Stage one's question fits beside the state
 * the person's context budget allows; stage two may take up to `timeoutMs` (a
 * caller with less left tells `rank` so: features/skills.ts, find-skill.ts).
 */
export function rankingSettings(ctx: { config: Pick<Config, 'timeoutMs' | 'context' | 'skills'>; ask: { language: Language } }): RankerSettings {
  return {
    language: ctx.ask.language,
    shortlist: ctx.config.skills.shortlist,
    questionTokens: questionBudget(ctx.config.context.tokens),
    timeoutMs: ctx.config.timeoutMs,
  }
}

/** One skill of the session, as the decision model is offered it. */
export type CatalogSkill = SkillOption & {
  /** Where it comes from, by the engine's word (`userSettings`, `plugin`, `built-in`, `syncedSkills`, ...). */
  source: string
  /** Its SKILL.md (or command file) on disk, found by Claude Code's layout; null when there is none to read (a built-in skill). */
  file: string | null
  /** The store key of its profile (core/profiles.ts), once looked up: it changes with the SKILL.md. */
  profileKey?: string | null
}

/** A command as `$.command.list()` gives it (the part read here). */
export type CommandLike = { name: string; description: string; source: string; plugin?: string }
/** A skill of the main agent's listing as the context counts it (`skillFrontmatter`; the part read here). */
export type ListedLike = { name: string; source: string; pluginName?: string }

/** The settings sources, lowest precedence first (as `$.settings.read({ source })` names them). */
export const SETTINGS_SOURCES = ['user', 'project', 'local', 'flag', 'policy'] as const
export type SettingsSourceName = (typeof SETTINGS_SOURCES)[number]

/** What the catalog reads of the session, as closures over `$`. */
export type CatalogIo = {
  /** `$.command.list()`: every command and skill the person can run, with its description. */
  commands: () => Promise<readonly CommandLike[]>
  /**
   * The skills the engine lists for the main agent, those the model may load
   * (`$.session.usage({ breakdown: 'summary' })`'s
   * `context.breakdown.skills.skillFrontmatter`; empty when it lists none).
   */
  listed: () => Promise<readonly ListedLike[]>
  /** One settings source's `skillOverrides` (`$.settings.read({ source })`), as the file holds it. */
  overrides: (source: SettingsSourceName) => Promise<unknown>
  /** `$.env.get('HOME')`. */
  home: () => Promise<string | undefined>
  /** `$.session.cwd()`. */
  cwd: () => Promise<string>
  /** `$.fs.exists(path)` (asked first: a read that fails leaves a line in the debug log). */
  exists: (path: string) => Promise<boolean>
  /** `$.fs.read(path)`: rejects when the file is missing. */
  read: (path: string) => Promise<string>
  /** `$.fs.list(path)`: a directory's entries (synced skills sit under an account directory only a listing names). */
  list: (path: string) => Promise<readonly { name: string; kind: string }[]>
}

/**
 * Claude.ai's synced skills: the context counts them by their bare name
 * (`computer-use`), the listing and the Skill tool name them with this prefix.
 */
const SYNCED_PREFIX = 'anthropic-skills:'

/** The name the Skill tool takes for a listed skill. */
function toolName(skill: ListedLike): string {
  return skill.source === 'syncedSkills' && !skill.name.includes(':') ? `${SYNCED_PREFIX}${skill.name}` : skill.name
}

/**
 * The session's skills: first those the engine lists for the main agent (the
 * model may load them), in its order; then those only the person can start,
 * the commands the engine keeps out of the listing whose SKILL.md (or command
 * file) sets `disable-model-invocation: true`, unless settings switch them
 * off. Each is described as `$.command.list()` describes it, with the file it
 * was found in. Rejects when the commands or the listing cannot be read; a
 * settings source or a file that cannot be read only leaves its part out.
 */
export async function loadCatalog(io: CatalogIo): Promise<CatalogSkill[]> {
  const [commands, listed] = await Promise.all([io.commands(), io.listed()])
  const descriptions = new Map<string, string>()
  for (const command of commands) if (!descriptions.has(command.name)) descriptions.set(command.name, command.description)
  const where = { home: await io.home().catch(() => undefined), cwd: await io.cwd().catch(() => undefined) }
  let installed: Promise<string> | undefined
  const installedPlugins = () => (installed ??= where.home ? readIfThere(io, `${where.home}/.claude/plugins/installed_plugins.json`).then((text) => text ?? '') : Promise.resolve(''))
  let accounts: Promise<string[]> | undefined
  const syncedAccounts = () => (accounts ??= syncedAccountsOf(io, where.home))

  const skills: CatalogSkill[] = []
  const seen = new Set<string>()
  const entries = listed.filter((entry) => {
    const name = toolName(entry)
    if (seen.has(name)) return false
    seen.add(name)
    return true
  })
  const files = await Promise.all(entries.map(async (entry) => firstExisting(io, await listedFiles(io, entry, where, installedPlugins, syncedAccounts))))
  entries.forEach((entry, i) => {
    const name = toolName(entry)
    const description = descriptions.get(entry.name) ?? descriptions.get(name) ?? ''
    skills.push({ name, description: description.trim(), by: 'model', source: entry.source, file: files[i] ?? null })
  })

  const listedAs = new Set(listed.map((entry) => entry.name))
  const overrides = await mergedOverrides(io)
  for (const command of commands) {
    if (command.source !== 'user' && command.source !== 'plugin') continue
    if (listedAs.has(command.name) || seen.has(command.name) || isOff(overrides, command.name)) continue
    const found = await firstThere(io, command.source === 'plugin' ? await pluginFiles(io, command, await installedPlugins()) : ownFiles(command.name, where))
    if (found === null || !reservedForPerson(found.text)) continue
    seen.add(command.name)
    skills.push({ name: command.name, description: command.description.trim(), by: 'person', source: command.source, file: found.path })
  }
  return skills
}

/**
 * Where a listed skill's file may be, by where the engine says it comes from:
 * the person's own under `~/.claude`, a project's under the working
 * directory, a plugin's under its install path, a synced one under its
 * account's directory. A built-in skill has no file.
 */
async function listedFiles(
  io: CatalogIo,
  entry: ListedLike,
  where: { home: string | undefined; cwd: string | undefined },
  installedPlugins: () => Promise<string>,
  syncedAccounts: () => Promise<string[]>,
): Promise<string[]> {
  switch (entry.source) {
    case 'userSettings':
      return ownFiles(entry.name, { home: where.home, cwd: undefined })
    case 'projectSettings':
    case 'localSettings':
      return ownFiles(entry.name, { home: undefined, cwd: where.cwd })
    case 'plugin':
      return pluginFiles(io, { name: entry.name, description: '', source: 'plugin', ...(entry.pluginName !== undefined ? { plugin: entry.pluginName } : {}) }, await installedPlugins())
    case 'syncedSkills': {
      const short = entry.name.slice(entry.name.lastIndexOf(':') + 1)
      if (!where.home || !safeName(short)) return []
      return (await syncedAccounts()).map((account) => `${where.home}/.claude/skills/synced/${account}/${short}/SKILL.md`)
    }
    default:
      return []
  }
}

/** The accounts whose synced skills sit under `~/.claude/skills/synced` (a directory each). */
async function syncedAccountsOf(io: CatalogIo, home: string | undefined): Promise<string[]> {
  if (!home) return []
  const entries = await io.list(`${home}/.claude/skills/synced`).catch(() => [])
  return entries.filter((entry) => entry.kind === 'dir' && safeName(entry.name)).map((entry) => entry.name)
}

/** `skillOverrides` over every settings source, a name taking the value of the highest source that sets it. */
async function mergedOverrides(io: CatalogIo): Promise<Map<string, unknown>> {
  const merged = new Map<string, unknown>()
  for (const source of SETTINGS_SOURCES) {
    const overrides = await io.overrides(source).catch(() => undefined)
    if (typeof overrides !== 'object' || overrides === null) continue
    for (const [name, value] of Object.entries(overrides)) merged.set(name, value)
  }
  return merged
}

/** Whether settings switch a skill off (by its own name, or a synced one's prefixed name). */
function isOff(overrides: ReadonlyMap<string, unknown>, name: string): boolean {
  return overrides.get(name) === 'off' || overrides.get(`${SYNCED_PREFIX}${name}`) === 'off'
}

/** Whether a name may go into a path: no separator, no `..`. */
function safeName(name: string): boolean {
  return name !== '' && !name.includes('/') && !name.includes('\\') && !name.split(':').includes('..')
}

/** Where a project or user skill (or command) of this name lives, the project's first. */
function ownFiles(name: string, where: { home: string | undefined; cwd: string | undefined }): string[] {
  if (!safeName(name)) return []
  const roots = [where.cwd, where.home].filter((root): root is string => typeof root === 'string' && root !== '')
  return roots.flatMap((root) => [`${root}/.claude/skills/${name}/SKILL.md`, `${root}/.claude/commands/${name.replace(/:/g, '/')}.md`])
}

/**
 * Where a plugin's skill (or command) lives, under each install path
 * `installed_plugins.json` records for the plugin: in the skill directories
 * its manifest names (`skills` in `.claude-plugin/plugin.json`, a path or
 * paths), then in `skills/`, then as a command.
 */
async function pluginFiles(io: CatalogIo, command: CommandLike, installedJson: string): Promise<string[]> {
  const plugin = command.plugin ?? command.name.split(':')[0] ?? ''
  const short = command.name.startsWith(`${plugin}:`) ? command.name.slice(plugin.length + 1) : command.name
  if (!safeName(plugin) || !safeName(short)) return []
  let parsed: unknown
  try {
    parsed = JSON.parse(installedJson)
  } catch {
    return []
  }
  const plugins = typeof parsed === 'object' && parsed !== null ? (parsed as { plugins?: unknown }).plugins : undefined
  if (typeof plugins !== 'object' || plugins === null) return []
  const files: string[] = []
  for (const [key, installs] of Object.entries(plugins)) {
    if (key !== plugin && !key.startsWith(`${plugin}@`)) continue
    for (const install of Array.isArray(installs) ? installs : []) {
      const path = (install as { installPath?: unknown } | null)?.installPath
      if (typeof path !== 'string') continue
      const root = path.replace(/\/+$/, '')
      for (const dir of await skillDirsOf(io, root)) files.push(`${root}/${dir}/${short}/SKILL.md`)
      files.push(`${root}/commands/${short.replace(/:/g, '/')}.md`)
    }
  }
  return files
}

/** A plugin's skill directories, relative to its root: those its manifest names (`skills`), then `skills`. */
async function skillDirsOf(io: CatalogIo, root: string): Promise<string[]> {
  const manifest = await readIfThere(io, `${root}/.claude-plugin/plugin.json`)
  let declared: unknown
  try {
    declared = manifest === null ? undefined : (JSON.parse(manifest) as { skills?: unknown }).skills
  } catch {
    declared = undefined
  }
  const named = (Array.isArray(declared) ? declared : [declared]).flatMap((dir) => {
    if (typeof dir !== 'string') return []
    const clean = dir.trim().replace(/^\.\/+/, '').replace(/\/+$/, '')
    return clean !== '' && !clean.startsWith('/') && !clean.split('/').includes('..') ? [clean] : []
  })
  return [...new Set([...named, 'skills'])]
}

/** A file's text, or null when it is not there or cannot be read. */
async function readIfThere(io: CatalogIo, path: string): Promise<string | null> {
  if (!(await io.exists(path).catch(() => false))) return null
  return io.read(path).catch(() => null)
}

/** The first of `files` that exists; null when none does. */
async function firstExisting(io: CatalogIo, files: readonly string[]): Promise<string | null> {
  for (const path of files) if (await io.exists(path).catch(() => false)) return path
  return null
}

/** The first of `files` that can be read, with its text; null when none can. */
async function firstThere(io: CatalogIo, files: readonly string[]): Promise<{ path: string; text: string } | null> {
  for (const path of files) {
    const text = await readIfThere(io, path)
    if (text !== null) return { path, text }
  }
  return null
}

/** Whether a SKILL.md's frontmatter sets `disable-model-invocation: true` (the model may not load it; the person runs `/name`). */
export function reservedForPerson(markdown: string): boolean {
  const frontmatter = /^﻿?---\r?\n([\s\S]*?)\r?\n---/.exec(markdown)
  if (!frontmatter) return false
  return /^disable-model-invocation:\s*(?:true|yes|on|"true"|'true')\s*(?:#.*)?$/im.test(frontmatter[1] as string)
}

/** One entry of the engine's skill listing: `- name: description`, a description possibly running on over more lines. */
type ListingEntry = { name: string; lines: string[] }

/** The listing's lines before its first entry (the header), and its entries in order. */
function readListing(text: string): { head: string[]; entries: ListingEntry[] } {
  const head: string[] = []
  const entries: ListingEntry[] = []
  for (const line of text.split('\n')) {
    // A name has no spaces and may itself hold `:` (`cloudflare:wrangler`): it runs to the first `: `.
    const entry = /^- (\S+?)(?::\s.*|:)?$/.exec(line)
    if (entry) entries.push({ name: entry[1] as string, lines: [line] })
    else if (entries.length > 0) (entries.at(-1) as ListingEntry).lines.push(line)
    else head.push(line)
  }
  return { head, entries }
}

/** The names the engine's skill listing gives, in order. */
export function listingNames(text: string): string[] {
  return readListing(text).entries.map((entry) => entry.name)
}

/**
 * The listing with only the skills in `keep` left in it, each as the engine
 * wrote it, under the engine's header; null when none of them is in it.
 */
export function trimListing(text: string, keep: ReadonlySet<string>): string | null {
  const { head, entries } = readListing(text)
  const kept = entries.filter((entry) => keep.has(entry.name))
  if (kept.length === 0) return null
  return [...head, ...kept.flatMap((entry) => entry.lines)].join('\n')
}

files.hooks/decision/workflow-script.ts:
// A Workflow script read just far enough to find its `agent()` calls, and to
// write a model and an effort into each one (#8).
//
// A script is plain JavaScript, and a mod has no JavaScript parser to import,
// so this reads it with a tokenizer that knows what a string, a template, a
// comment and a regular expression are. It finds each call's arguments, and
// edits the script as text, only at the spots it found: everything else comes
// back exactly as it was written. Anything it cannot read with confidence is
// left alone, never guessed at.
//
// Pure (see system-one.ts): no `$`; the mod, its tests and Node import it as it is.

/** One `agent()` call of a script, as far as it could be read. */
export type AgentCall = {
  /** Its place among the script's `agent()` calls in source order, from 0. */
  index: number
  /** The line it starts on, from 1. */
  line: number
  /** The prompt as written (a template keeps its `${...}`), for the decision model; null when the script builds it at run time. */
  prompt: string | null
  /** The `label` option as written; null when there is none or it is built at run time. */
  label: string | null
  /**
   * How the call writes its label: not at all (the engine then records the
   * agent under the start of its prompt, #9), a string, a template (`label`
   * keeps its `${...}`), or something worked out when the script runs (an
   * expression, a spread that may hold one, options that are not an object).
   */
  labelKind: 'none' | 'string' | 'template' | 'dynamic'
  /** The `agentType` option when it is a string; null otherwise. */
  agentType: string | null
  /** The `model` option: absent, a string the script wrote, or some other expression (`dynamic`). */
  model: Written
  /** The `effort` option, read the same way. */
  effort: Written
  /** Where the edits go (internal to `rewriteWorkflow`); null for a call whose options cannot be edited. */
  edit: CallEdit | null
}

/** An option of a call: not written, a string the script wrote, or an expression it works out when it runs. */
export type Written = { kind: 'none' } | { kind: 'literal'; value: string } | { kind: 'dynamic' }

/** What `parseWorkflow` reads of a script. */
export type ParsedWorkflow = {
  /** The script itself, which `rewriteWorkflow` edits. */
  script: string
  /** What the script's `meta` block says about the workflow. */
  meta: { name: string | null; description: string | null }
  /** Every `agent()` call, in source order. */
  calls: AgentCall[]
}

/** What to write into one call: a model, an effort (`null` takes out the one the script wrote). */
export type CallWrite = { model?: string; effort?: string | null }

/** Where one call takes its edits: its options object, or the spot an options argument goes. */
type CallEdit = { kind: 'object'; object: ObjectLiteral } | { kind: 'append'; at: number; trailingComma: boolean }

/** One property of an options object literal. */
type Property = {
  /** The key when it is a plain identifier or a string (a shorthand `model` has one too); null for a spread, a computed key or a method. */
  key: string | null
  start: number
  end: number
  /** The value of `key: value`: where it is, and its text when it is a plain string or a template. */
  value: { start: number; end: number; text: string | null; interpolated: boolean } | null
}

/** An object literal's braces and properties. */
type ObjectLiteral = {
  open: number
  close: number
  properties: Property[]
  /** Where the last property's trailing comma ends, when it has one. */
  trailingCommaEnd: number | null
}

/** A lexical token; a template literal carries the code of its `${...}` as streams of their own. */
type Token = { kind: 'id' | 'num' | 'str' | 'tpl' | 're' | 'p'; text: string; start: number; end: number; streams?: Stream[] }

/** The tokens of a stretch of code, and for each opening bracket the index of its closing one. */
type Stream = { tokens: Token[]; pairs: Map<number, number> }

/**
 * Reads a Workflow script. Null when it cannot be read with confidence (an
 * unterminated string, brackets that do not pair, no `meta` block): the
 * caller leaves such a script alone.
 */
export function parseWorkflow(script: string): ParsedWorkflow | null {
  const lexed = lexStream(script, 0, false)
  if (lexed === null) return null
  const meta = readMeta(script, lexed.stream)
  if (meta === null) return null
  const calls: AgentCall[] = []
  findCalls(script, lexed.stream, calls, lineCounter(script))
  calls.forEach((call, index) => (call.index = index))
  return { script, meta, calls }
}

/**
 * The script with `writes[i]` written into its call `i` (`null`: the call is
 * left as it is). A model or effort goes into the call's options object, in
 * place of the one the script wrote or after the last property; a call
 * without options gets an object. Nothing else changes.
 */
export function rewriteWorkflow(parsed: ParsedWorkflow, writes: readonly (CallWrite | null)[]): string {
  const edits: Edit[] = []
  for (const call of parsed.calls) {
    const write = writes[call.index]
    if (write === undefined || write === null || call.edit === null) continue
    const edit = call.edit
    if (edit.kind === 'append') {
      const added = entriesOf(write)
      if (added.length > 0) edits.push({ start: edit.at, end: edit.at, text: `${edit.trailingComma ? ' ' : ', '}{ ${added.join(', ')} }` })
    } else {
      edits.push(...objectEdits(parsed.script, edit.object, write))
    }
  }
  // In one pass over the script. An edit that starts inside the one before it
  // (a call in a value that was replaced) is dropped: its text is gone.
  const pieces: string[] = []
  let at = 0
  for (const edit of edits.sort((a, b) => a.start - b.start)) {
    if (edit.start < at) continue
    pieces.push(parsed.script.slice(at, edit.start), edit.text)
    at = edit.end
  }
  pieces.push(parsed.script.slice(at))
  return pieces.join('')
}

type Edit = { start: number; end: number; text: string }

/** The `model: 'x'` and `effort: 'y'` entries a write adds to an options object. */
function entriesOf(write: CallWrite): string[] {
  const entries: string[] = []
  if (write.model !== undefined) entries.push(`model: '${write.model}'`)
  if (typeof write.effort === 'string') entries.push(`effort: '${write.effort}'`)
  return entries
}

/**
 * The edits that put a write into an options object: the value of a `model`
 * or `effort` the script already wrote is replaced where it stands; one it
 * did not write goes after the last property. An effort to take out means the
 * object is written out again from its properties, without it.
 */
function objectEdits(src: string, object: ObjectLiteral, write: CallWrite): Edit[] {
  // The last property of a key is the one that counts, as in JavaScript.
  const existing = (key: string): Property | undefined => object.properties.findLast((property) => property.key === key)
  // What a property the script wrote is replaced with: its value, or all of it when it is a shorthand (`{ model }`).
  const replaced = new Map<Property, Edit>()
  const added: string[] = []
  let removed: Property | undefined
  const set = (key: 'model' | 'effort', value: string) => {
    const at = existing(key)
    if (at === undefined) added.push(`${key}: '${value}'`)
    else if (at.value !== null) replaced.set(at, { start: at.value.start, end: at.value.end, text: `'${value}'` })
    else replaced.set(at, { start: at.start, end: at.end, text: `${key}: '${value}'` })
  }
  if (write.model !== undefined) set('model', write.model)
  if (typeof write.effort === 'string') set('effort', write.effort)
  else if (write.effort === null) removed = existing('effort')
  if (removed !== undefined) {
    const kept = object.properties.filter((property) => property !== removed).map((property) => propertyText(src, property, replaced.get(property)))
    const body = [...kept, ...added].join(', ')
    return [{ start: object.open, end: object.close + 1, text: body === '' ? '{}' : `{ ${body} }` }]
  }
  const edits: Edit[] = [...replaced.values()]
  if (added.length > 0) {
    const text = added.join(', ')
    const last = object.properties[object.properties.length - 1]
    if (last === undefined) edits.push({ start: object.open, end: object.close + 1, text: `{ ${text} }` })
    else if (object.trailingCommaEnd !== null) edits.push({ start: object.trailingCommaEnd, end: object.trailingCommaEnd, text: ` ${text}` })
    else edits.push({ start: last.end, end: last.end, text: `, ${text}` })
  }
  return edits
}

/** A property's source text, with `edit` (a span inside it) applied when given. */
function propertyText(src: string, property: Property, edit: Edit | undefined): string {
  if (edit === undefined) return src.slice(property.start, property.end)
  return src.slice(property.start, edit.start) + edit.text + src.slice(edit.end, property.end)
}

// --- tokens -----------------------------------------------------------------

/** Words after which a `/` starts a regular expression rather than dividing. */
const BEFORE_REGEX = new Set(['return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw', 'case', 'do', 'else', 'yield', 'await'])

const ID_START = /[\p{ID_Start}_$]/u
// An identifier may also hold the zero-width joiners U+200C and U+200D.
const ID_PART = new RegExp(`[\\p{ID_Continue}$${String.fromCharCode(0x200c, 0x200d)}]`, 'u')

/**
 * The tokens of the code from `from`: to the end of the script, or (inside a
 * template's `${`) to the `}` that closes it, whose offset is `end`. Null
 * when the code cannot be read: a string, template, comment or bracket that
 * does not end.
 */
function lexStream(src: string, from: number, inTemplate: boolean): { stream: Stream; end: number } | null {
  const tokens: Token[] = []
  let depth = 0
  let i = from
  const finish = (end: number): { stream: Stream; end: number } | null => {
    const pairs = pairBrackets(tokens)
    return pairs === null ? null : { stream: { tokens, pairs }, end }
  }
  while (i < src.length) {
    const c = src.charAt(i)
    const next = src.charAt(i + 1)
    if (/\s/.test(c)) {
      i++
    } else if (c === '/' && next === '/') {
      const end = src.indexOf('\n', i)
      i = end < 0 ? src.length : end + 1
    } else if (c === '/' && next === '*') {
      const end = src.indexOf('*/', i + 2)
      if (end < 0) return null
      i = end + 2
    } else if (c === "'" || c === '"') {
      const end = endOfString(src, i)
      if (end === null) return null
      tokens.push({ kind: 'str', text: src.slice(i, end), start: i, end })
      i = end
    } else if (c === '`') {
      const template = lexTemplate(src, i)
      if (template === null) return null
      tokens.push(template)
      i = template.end
    } else if (c === '/' && regexAllowed(tokens.at(-1)) && endOfRegex(src, i) !== null) {
      const end = endOfRegex(src, i) as number
      tokens.push({ kind: 're', text: src.slice(i, end), start: i, end })
      i = end
    } else if (ID_START.test(c)) {
      let end = i + 1
      while (end < src.length && ID_PART.test(src.charAt(end))) end++
      tokens.push({ kind: 'id', text: src.slice(i, end), start: i, end })
      i = end
    } else if (/[0-9]/.test(c) || (c === '.' && /[0-9]/.test(next))) {
      let end = i + 1
      while (end < src.length && /[0-9A-Za-z_.]/.test(src.charAt(end))) end++
      tokens.push({ kind: 'num', text: src.slice(i, end), start: i, end })
      i = end
    } else if (c === '.' && next === '.' && src.charAt(i + 2) === '.') {
      tokens.push({ kind: 'p', text: '...', start: i, end: i + 3 })
      i += 3
    } else {
      if (c === '}' && inTemplate && depth === 0) return finish(i)
      if (c === '{') depth++
      else if (c === '}') depth--
      tokens.push({ kind: 'p', text: c, start: i, end: i + 1 })
      i++
    }
  }
  return inTemplate ? null : finish(src.length)
}

/** The template literal that starts at `start`: one token, its `${...}` code lexed as streams of their own; null when it never ends. */
function lexTemplate(src: string, start: number): Token | null {
  const streams: Stream[] = []
  let i = start + 1
  while (i < src.length) {
    const c = src.charAt(i)
    if (c === '\\') {
      i += 2
    } else if (c === '`') {
      return { kind: 'tpl', text: src.slice(start, i + 1), start, end: i + 1, streams }
    } else if (c === '$' && src.charAt(i + 1) === '{') {
      const inner = lexStream(src, i + 2, true)
      if (inner === null) return null
      streams.push(inner.stream)
      i = inner.end + 1
    } else {
      i++
    }
  }
  return null
}

/** Whether a `/` after `previous` starts a regular expression (it divides after a value, a closing `)` or `]`). */
function regexAllowed(previous: Token | undefined): boolean {
  if (previous === undefined) return true
  switch (previous.kind) {
    case 'id':
      return BEFORE_REGEX.has(previous.text)
    case 'num':
    case 'str':
    case 'tpl':
    case 're':
      return false
    default:
      return previous.text !== ')' && previous.text !== ']'
  }
}

/** Where the regular expression that starts at `start` ends (past its flags); null when it does not close on its line, so the `/` divides. */
function endOfRegex(src: string, start: number): number | null {
  let i = start + 1
  let inClass = false
  while (i < src.length) {
    const c = src.charAt(i)
    if (c === '\n') return null
    if (c === '\\') i++
    else if (c === '[') inClass = true
    else if (c === ']') inClass = false
    else if (c === '/' && !inClass) {
      i++
      while (i < src.length && /[A-Za-z]/.test(src.charAt(i))) i++
      return i
    }
    i++
  }
  return null
}

/** Where the string that starts at `start` ends (just past its closing quote); null when it never closes on its line. */
function endOfString(src: string, start: number): number | null {
  const quote = src.charAt(start)
  let i = start + 1
  while (i < src.length) {
    const c = src.charAt(i)
    if (c === '\\') i++
    else if (c === quote) return i + 1
    else if (c === '\n') return null
    i++
  }
  return null
}

const OPENERS: Record<string, string> = { '(': ')', '[': ']', '{': '}' }

/** For each opening bracket's token index, its closing bracket's; null when they do not pair. */
function pairBrackets(tokens: readonly Token[]): Map<number, number> | null {
  const pairs = new Map<number, number>()
  const open: number[] = []
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i] as Token
    if (token.kind !== 'p') continue
    if (token.text in OPENERS) {
      open.push(i)
    } else if (token.text === ')' || token.text === ']' || token.text === '}') {
      const at = open.pop()
      if (at === undefined || OPENERS[(tokens[at] as Token).text] !== token.text) return null
      pairs.set(at, i)
    }
  }
  return open.length === 0 ? pairs : null
}

// --- meta -------------------------------------------------------------------

/** What the script's `export const meta = { ... }` says (its name and description when they are strings); null when the script has no such block. */
function readMeta(src: string, stream: Stream): ParsedWorkflow['meta'] | null {
  const { tokens, pairs } = stream
  for (let i = 0; i + 4 < tokens.length; i++) {
    if (!['export', 'const', 'meta', '=', '{'].every((text, k) => (tokens[i + k] as Token).text === text)) continue
    const object = readObject(src, stream, i + 4, pairs.get(i + 4) as number)
    if (object === null) return null
    const text = (key: string): string | null => {
      const value = object.properties.find((property) => property.key === key)?.value
      return value !== undefined && value !== null && !value.interpolated ? value.text : null
    }
    return { name: text('name'), description: text('description') }
  }
  return null
}

// --- calls ------------------------------------------------------------------

/** Adds the `agent()` calls of a stream, and of the code in its templates, to `calls`, in source order. */
function findCalls(src: string, stream: Stream, calls: AgentCall[], lineOf: (offset: number) => number): void {
  const { tokens } = stream
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i] as Token
    if (token.kind === 'tpl') {
      for (const inner of token.streams ?? []) findCalls(src, inner, calls, lineOf)
    } else if (isAgentCall(src, stream, i)) {
      const call = readCall(src, stream, i, lineOf)
      if (call !== null) calls.push(call)
    }
  }
}

/** Whether token `i` is the `agent` of a call `agent(`: not a member (`x.agent(`), a declaration, a constructor call or a method definition. */
function isAgentCall(src: string, stream: Stream, i: number): boolean {
  const { tokens, pairs } = stream
  const token = tokens[i] as Token
  if (token.kind !== 'id' || token.text !== 'agent' || tokens[i + 1]?.text !== '(') return false
  const before = tokens[i - 1]
  if (before !== undefined && (before.text === '.' || before.text === 'function' || before.text === 'new')) return false
  // `agent(prompt) {` on one line defines a method; a call is not followed by a block.
  const close = tokens[pairs.get(i + 1) as number] as Token
  const after = tokens[(pairs.get(i + 1) as number) + 1]
  return !(after !== undefined && after.text === '{' && !src.slice(close.end, after.start).includes('\n'))
}

/** The arguments of the call whose `(` is token `open`: each one's first and last token index (inclusive), and whether a comma trails the last. */
function splitArguments(stream: Stream, open: number): { args: { first: number; last: number }[]; trailingComma: boolean } {
  const { tokens, pairs } = stream
  const close = pairs.get(open) as number
  const args: { first: number; last: number }[] = []
  let first = open + 1
  let trailingComma = false
  for (let i = open + 1; i < close; i++) {
    const token = tokens[i] as Token
    if (token.kind === 'p' && token.text in OPENERS) {
      i = pairs.get(i) as number
    } else if (token.kind === 'p' && token.text === ',') {
      if (i > first) args.push({ first, last: i - 1 })
      first = i + 1
      trailingComma = i === close - 1
    }
  }
  if (close > first) args.push({ first, last: close - 1 })
  return { args, trailingComma }
}

function readCall(src: string, stream: Stream, at: number, lineOf: (offset: number) => number): AgentCall | null {
  const { tokens, pairs } = stream
  const open = at + 1
  const { args, trailingComma } = splitArguments(stream, open)
  const promptArg = args[0]
  if (promptArg === undefined || args.length > 2 || (tokens[promptArg.first] as Token).text === '...') return null
  const call: AgentCall = {
    index: 0,
    line: lineOf((tokens[at] as Token).start),
    prompt: textOf(src, tokens, promptArg.first, promptArg.last)?.text ?? null,
    label: null,
    labelKind: 'none',
    agentType: null,
    model: { kind: 'none' },
    effort: { kind: 'none' },
    edit: null,
  }
  const optionsArg = args[1]
  if (optionsArg === undefined) {
    // After the prompt, or after the comma that trails it.
    const close = pairs.get(open) as number
    call.edit = { kind: 'append', at: (tokens[trailingComma ? close - 1 : promptArg.last] as Token).end, trailingComma }
    return call
  }
  const object = readObject(src, stream, optionsArg.first, optionsArg.last)
  if (object === null) {
    call.labelKind = 'dynamic'
    return call
  }
  call.edit = { kind: 'object', object }
  // A spread or a computed key may hold a label.
  if (object.properties.some((property) => property.key === null)) call.labelKind = 'dynamic'
  for (const property of object.properties) {
    const text = property.value !== null && !property.value.interpolated ? property.value.text : null
    if (property.key === 'label') {
      call.label = property.value?.text ?? null
      call.labelKind = property.value === null || property.value.text === null ? 'dynamic' : property.value.interpolated ? 'template' : 'string'
    } else if (property.key === 'agentType') call.agentType = text
    else if (property.key === 'model') call.model = text === null ? { kind: 'dynamic' } : { kind: 'literal', value: text }
    else if (property.key === 'effort') call.effort = text === null ? { kind: 'dynamic' } : { kind: 'literal', value: text }
  }
  return call
}

/** The object literal that is exactly tokens `first`..`last`; null when those tokens are anything else. */
function readObject(src: string, stream: Stream, first: number, last: number): ObjectLiteral | null {
  const { tokens, pairs } = stream
  const open = tokens[first] as Token
  if (open.text !== '{' || pairs.get(first) !== last) return null
  const properties: Property[] = []
  let start = first + 1
  let trailingCommaEnd: number | null = null
  const push = (from: number, to: number) => {
    const head = tokens[from] as Token
    const colon = tokens[from + 1]
    const plain = (head.kind === 'id' || head.kind === 'str') && colon?.text === ':' && to > from + 1
    const shorthand = head.kind === 'id' && from === to
    const text = plain ? textOf(src, tokens, from + 2, to) : null
    properties.push({
      key: plain || shorthand ? (head.kind === 'str' ? (textOf(src, tokens, from, from)?.text ?? null) : head.text) : null,
      start: head.start,
      end: (tokens[to] as Token).end,
      value: plain ? { start: (tokens[from + 2] as Token).start, end: (tokens[to] as Token).end, text: text?.text ?? null, interpolated: text?.interpolated ?? false } : null,
    })
  }
  for (let i = first + 1; i < last; i++) {
    const token = tokens[i] as Token
    if (token.kind === 'p' && token.text in OPENERS) {
      i = pairs.get(i) as number
    } else if (token.kind === 'p' && token.text === ',') {
      if (i > start) push(start, i - 1)
      trailingCommaEnd = i === last - 1 ? token.end : null
      start = i + 1
    }
  }
  if (last > start) push(start, last - 1)
  return { open: open.start, close: (tokens[last] as Token).start, properties, trailingCommaEnd }
}

// --- text -------------------------------------------------------------------

/** The text of tokens `first`..`last` when they are one string or one template; a template keeps its `${...}` as written. */
function textOf(src: string, tokens: readonly Token[], first: number, last: number): { text: string; interpolated: boolean } | null {
  if (first !== last) return null
  const token = tokens[first] as Token
  if (token.kind === 'str') return { text: stringValue(token.text), interpolated: false }
  if (token.kind === 'tpl') return { text: src.slice(token.start + 1, token.end - 1), interpolated: (token.streams ?? []).length > 0 }
  return null
}

/** The line (from 1) of an offset; asked for in source order, it counts each line break once. */
function lineCounter(src: string): (offset: number) => number {
  let at = 0
  let line = 1
  return (offset) => {
    if (offset < at) {
      at = 0
      line = 1
    }
    for (; at < offset; at++) if (src.charCodeAt(at) === 10) line++
    return line
  }
}

const ESCAPES: Record<string, string> = { n: '\n', t: '\t', r: '\r', b: '\b', f: '\f', v: '\v', '0': '\0' }

/** The value of a string literal's source text. */
function stringValue(literal: string): string {
  return literal.slice(1, -1).replace(/\\(?:u\{([0-9a-fA-F]+)\}|u([0-9a-fA-F]{4})|x([0-9a-fA-F]{2})|(\r\n|[\s\S]))/g, (_, braced?: string, unicode?: string, hex?: string, plain?: string) => {
    const code = braced ?? unicode ?? hex
    if (code !== undefined) return String.fromCodePoint(Number.parseInt(code, 16))
    if (plain === '\n' || plain === '\r\n') return ''
    return ESCAPES[plain as string] ?? (plain as string)
  })
}

