{
  "name": "dispatch-pilot",
  "version": "0.2.3",
  "description": "Dispatch Pilot: a decision model outside Claude (Jev or Clef, your choice) picks the main agent's reasoning effort each time you send a message (and when an agent's report or a task notice starts a turn), sets it on every request of the turn, and decides it again every few steps while the turn runs. It also picks the model and effort of each agent the main agent dispatches and of each agent a Workflow script starts, by Artificial Analysis benchmarks (sonnet and opus at medium effort at least). The main agent's model never changes, so the prompt cache survives (on a Claude Code subscription; not on Bedrock, Vertex or a gateway, where switching effort breaks the cache). It also keeps the full skill listing out of the main agent's context and suggests the few skills that fit each message; mid-turn, the main agent can look skills up with the find_skill tool. When an agent's tool calls keep failing it raises that agent's effort (a failing haiku agent goes on as sonnet), unless the failures are what the work expects.",
  "author": {
    "name": "alexcz-a11y",
    "url": "https://github.com/alexcz-a11y"
  },
  "repository": "https://github.com/alexcz-a11y/claude-mods",
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "decisionModel": {
      "type": "string",
      "title": "Decision model",
      "description": "Which model makes the decisions: jev (TypeSafe; needs the TypeSafe API key) or clef (Cloudflare Workers AI; needs the Cloudflare account ID and API token). The other is never used as a fallback: when the chosen one fails, the message goes on unrouted. Some options default by the model chosen. With Jev they are set to what Jev accepts (up to 32 recent messages and 16 steps; a context budget of 6000 tokens for a message that carries the skill question, 24000 for the other requests). With Clef, which answers more slowly and sometimes reads only the start of a long request, the decision timeout is 3000 ms, the context budget at most 2000 tokens for every kind of request (4 messages, 4 steps), and skill suggestions start off (/dp skills on turns them on).",
      "options": [
        "jev",
        "clef"
      ],
      "default": "jev"
    },
    "typesafeApiKey": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "Key for TypeSafe's System One API, where Jev runs (used when the decision model is jev). Without one, nothing is sent and every turn keeps the session's effort.",
      "default": "",
      "sensitive": true
    },
    "cloudflareAccountId": {
      "type": "string",
      "title": "Cloudflare account ID",
      "description": "The Cloudflare account that runs Workers AI (used when the decision model is clef). It is part of the request address, which Claude Code's debug log records. Without it, nothing is sent and every turn keeps the session's effort.",
      "default": "",
      "sensitive": true
    },
    "cloudflareApiToken": {
      "type": "string",
      "title": "Cloudflare Workers AI API token",
      "description": "A Cloudflare API token that can run Workers AI (used when the decision model is clef): in the dashboard, Workers AI, Use REST API, Create a Workers AI API Token. Without one, nothing is sent and every turn keeps the session's effort.",
      "default": "",
      "sensitive": true
    },
    "timeoutMs": {
      "type": "number",
      "title": "Decision timeout (ms)",
      "description": "How long a message waits for the decision model (200 to 8000). Past it the message goes on unrouted, at the session's effort, and the status line says so. Default: 1500 with Jev, 3000 with Clef, which answers more slowly (a first request often takes 1.5 s or more)."
    },
    "contextMessages": {
      "type": "number",
      "title": "Recent messages sent",
      "description": "How many recent messages the decision model reads beside yours (0 to 32): their text and the names of the tools they called, never file contents or tool output, secrets masked. Default 32 with Jev (the context budget, not this count, ends what is sent), 4 with Clef."
    },
    "contextTokens": {
      "type": "number",
      "title": "Context budget (tokens)",
      "description": "How many tokens your message and the recent messages may take together (100 to 16000; with Clef at most 2000), counted the same way for Chinese and English; older messages are dropped first. Read by kind of request: with Jev, 6000 for a message that carries the skill suggestions' question (and find_skill's first stage), which holds every skill's profile (about 22k tokens as Jev counts them) and so must keep the state plus the question within Jev's 32k, and 24000 for the other requests (a message without the skill question, a re-decision, a dispatched agent, a Workflow batch), whose questions are short. A value you set holds for every kind, each kind taking the smaller of it and its own. If decisions time out more often, set it lower. Default 2000 with Clef for every kind, and a larger value reads as 2000: Clef sometimes reads only about the first 2,100 tokens of what it is sent, and the newest messages come last, so they would be the ones lost."
    },
    "thetaMax": {
      "type": "number",
      "title": "Threshold for max effort",
      "description": "The main agent goes to max only when the decision model gives max at least this probability (0 to 1); otherwise it gets the most likely of the other levels. Default 0.5 with either decision model (not calibrated for Clef: Jev's value)."
    },
    "rejudgeEvery": {
      "type": "number",
      "title": "Re-decide effort every N steps",
      "description": "While a turn runs, the main agent's effort is decided again at every Nth step (0 to 50; 0 turns this off). Dispatching an agent, starting a Workflow or loading a skill also re-decides it.",
      "default": 3
    },
    "thetaUp": {
      "type": "number",
      "title": "Threshold to raise effort mid-turn",
      "description": "A re-decision raises the effort only when the decision model's confidence is at least this (0 to 1). Default 0.3 with either decision model (not calibrated for Clef, whose confidence runs much lower than Jev's: Jev's value)."
    },
    "thetaDown": {
      "type": "number",
      "title": "Threshold to lower effort mid-turn",
      "description": "A re-decision lowers the effort, by one level at most, only when the decision model's confidence is at least this (0 to 1; never below the raise threshold). Default 0.55 with either decision model (not calibrated for Clef: Jev's value)."
    },
    "holdSteps": {
      "type": "number",
      "title": "Steps before effort may drop after a raise",
      "description": "After a re-decision raises the effort, it does not lower it again for this many steps (0 to 50).",
      "default": 5
    },
    "rejudgeSteps": {
      "type": "number",
      "title": "Recent steps read when re-deciding",
      "description": "How many of the turn's latest steps the decision model reads when it re-decides (1 to 16): the main agent's last text and the tools it called with how each ended, never file contents or tool output, secrets masked. The context budget bounds them too. Default 16 with Jev (the context budget, not this count, ends what is sent), 4 with Clef."
    },
    "rejudgeWaitMs": {
      "type": "number",
      "title": "Wait for a late re-decision (ms)",
      "description": "A re-decision is asked while a tool runs; if it is not back when the next request goes out, that request waits this long for it (0 to 2000), then keeps the effort it had and the status line says so.",
      "default": 300
    },
    "escalateAfter": {
      "type": "number",
      "title": "Failed tool calls before escalating",
      "description": "The main agent, or an agent it dispatched, whose tool calls have failed this many times is asked about again and raised to a higher effort (1 to 20), unless the failures are what the work expects (a test written to fail first, a search that finds nothing). A call you refused yourself never counts; one of your own hooks blocked counts only after /dp hook-block-failures on.",
      "default": 2
    },
    "escalateMode": {
      "type": "string",
      "title": "How escalating raises the effort",
      "description": "one-level: one level up, never past xhigh (the decision model's own pick may go higher when it is sure). max: straight to max. A haiku agent has no effort to raise: it is switched to the model below instead.",
      "options": [
        "one-level",
        "max"
      ],
      "default": "one-level"
    },
    "escalateLimit": {
      "type": "number",
      "title": "Escalations per turn",
      "description": "How many times one turn of the main agent (or one dispatched agent) may be raised for failing tool calls (0 to 10). The failures count from zero again after each escalation.",
      "default": 2
    },
    "thetaExpected": {
      "type": "number",
      "title": "Threshold to find failures expected",
      "description": "When the decision model rates the failures at least this likely to be what the work expects (0 to 1), nothing is forced: the failures start counting from zero and the effort is left to the ordinary mid-turn rules. Low on purpose: measured on a few hand-written cases, Jev rates failures that are expected 0.15 to 0.72 and ones that are not 0.09 to 0.16 (Clef 0.27 to 0.90 and 0.03 to 0.11). Default 0.25 with either decision model (not calibrated for Clef: Jev's value)."
    },
    "escalateHaikuTo": {
      "type": "string",
      "title": "Model a failing haiku agent switches to",
      "description": "A haiku agent has no effort to raise, so when its tool calls keep failing it goes on as this model for the rest of its run: sonnet, opus or fable, or a full model id. An alias is turned into the full id a step needs (the engine takes no alias for a step); a model you named for the agent's work, or ruled out, holds over it. Empty: never switch.",
      "default": "sonnet"
    },
    "agentFable": {
      "type": "boolean",
      "title": "Let dispatched agents run on fable",
      "description": "Adds fable to the models the decision model may choose for an agent the main agent dispatches (haiku, sonnet and opus otherwise). Fable costs more than opus. A model you name yourself in your message is used either way.",
      "default": false
    },
    "agentOverride": {
      "type": "number",
      "title": "Confidence to override the main agent's model pick",
      "description": "When the main agent names a model for an agent it dispatches, the decision model's pick replaces it only at this confidence or above (0 to 1). A model you name yourself in your message is never replaced. Default 0.6 with either decision model (not calibrated for Clef: Jev's value)."
    },
    "skillsMax": {
      "type": "number",
      "title": "Skills suggested at most",
      "description": "How many skills one message gets suggested at most (0 to 10); fewer, or none, when fewer reach the relevance below.",
      "default": 3
    },
    "skillsMinRelevance": {
      "type": "number",
      "title": "Least relevance to suggest",
      "description": "The relevance a skill needs to be suggested (0 to 1): how likely the decision model judges that the skill does the kind of work the message asks for, each skill judged on its own after its instructions are re-read. Default 0.75 with either decision model (not calibrated for Clef: Jev's value)."
    },
    "skillsShortlist": {
      "type": "number",
      "title": "Skills re-read in the second stage",
      "description": "How many of the skills the main agent can load, rated highest for a message, are re-read with the opening of their instructions and judged one by one (1 to 10); at most 2 of the skills only you can start are re-read beside them. A skill is re-read only when the first request rated it at least 0.1, and both requests together wait at most the decision timeout.",
      "default": 4
    },
    "skillsProfileModel": {
      "type": "string",
      "title": "Model that writes skill profiles",
      "description": "The model (an alias such as haiku, or a full model id) that writes each skill a short profile in English and Chinese from its SKILL.md, once per version of the file, so the decision model can match a request in either language. It runs in the background through your Claude Code login and uses your plan's usage. A new model writes every profile again.",
      "default": "haiku"
    },
    "skillsProfilesPerSession": {
      "type": "number",
      "title": "Skill profiles written per session",
      "description": "How many missing skill profiles are written at most each time a session starts (0 to 500; 0 writes none). The rest wait for later sessions, so a first run with many skills spreads its cost.",
      "default": 30
    },
    "skillsAlwaysListed": {
      "type": "string",
      "multiple": true,
      "title": "Skills always listed",
      "description": "Skills the main agent keeps seeing in its skill listing, by the name the listing gives them (a synced skill with its prefix, such as anthropic-skills:pdf). Every other skill is left out of the listing and suggested only when a message needs it.",
      "default": []
    },
    "skillsNeverSuggested": {
      "type": "string",
      "multiple": true,
      "title": "Skills never suggested",
      "description": "Skills never suggested to the main agent nor pointed out to you, by the name the listing gives them. They stay installed: the Skill tool still loads one by name. find_skill never returns them either.",
      "default": []
    },
    "findSkillMax": {
      "type": "number",
      "title": "Skills find_skill returns at most",
      "description": "How many skills the main agent's find_skill tool returns for one query at most (1 to 10); fewer, or none, when fewer reach the relevance below.",
      "default": 5
    },
    "findSkillMinRelevance": {
      "type": "number",
      "title": "Least relevance find_skill returns",
      "description": "The relevance a skill needs for find_skill to return it (0 to 1): how likely the decision model judges that the skill does the kind of work the main agent names, each skill judged on its own after its instructions are re-read. Default 0.5 with either decision model (not calibrated for Clef: Jev's value)."
    },
    "workflowMode": {
      "type": "string",
      "title": "How Workflow agents are routed",
      "description": "rewrite: when the main agent submits a Workflow, the model and effort decided for each agent() call are written into the script before it runs, and the main agent is told what was written. return: the first submission of a Workflow is refused with the recommendation for each agent() call, for the main agent to write in itself; the same Workflow submitted again runs as written.",
      "options": [
        "rewrite",
        "return"
      ],
      "default": "rewrite"
    }
  }
}

files.types/index.d.ts:
// dispatch-pilot's $.state contract (PluginState), by key. Hand-written and
// committed; `claude plugin validate` checks every $.state read and write
// against it. No top-level export: a contract declares types and nothing else.
//
// The shapes mirror hooks/core/plans.ts (Plan, TurnRecord, PendingDecision);
// tsc checks the two agree wherever the hooks read or write these values.

declare module 'claude-code' {
  interface PluginState {
    'dispatch-pilot': {
      /**
       * Effort decided for the person's message at prompt.submit, waiting for
       * the turn that message starts (core's turn.start takes it); oldest
       * first, at most 16. `effort` null: the decision failed (the turn is
       * still the person's own, so mid-turn re-decisions may route it).
       */
      pending: { text: string; effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null; at: number; report?: true }[]
      /**
       * One record per turn of each loop, id `<loop>:<turnId>` where loop is
       * `main` or the agentId. The core's turn.step writer sends what it says.
       */
      turns: StateFamily<{
        /** The routed effort: the latest decision; null leaves the engine's. */
        effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        /** No step of the turn goes below it while it holds (forced raises); null for none. */
        floor: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        /** The model to name, for a dispatched or workflow agent only; never sent for main. */
        model: string | null
        /** The text the turn started with (main), redacted and clipped; '' when unknown. */
        prompt: string
        /** Decisions made for the turn: the one at its start plus re-decisions. */
        decisions: number
        /** Times the routed effort moved from one decided level to another. */
        changes: number
        /** Whether the person's own message started the turn (decided at its start or not). */
        person: boolean
        /** The step from which `floor` no longer holds; null: for the rest of the turn. */
        floorUntil: number | null
        /** The step the turn's effort last went up mid-turn (re-decided or forced); null when it has not. */
        raisedAt: number | null
      }>
      /**
       * A plan for every turn of one dispatched or workflow agent, id = agentId
       * (written at agent.spawn, or once the agent is known); a turn-level
       * plan of that agent wins over it slot by slot. `terms`: what the person
       * asked of its work in their own words (the model and the effort they
       * named, the models they ruled out); whatever changes the agent's model
       * or effort keeps to them.
       */
      agents: StateFamily<{
        effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        floor: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        model: string | null
        terms: {
          model: 'haiku' | 'sonnet' | 'opus' | 'fable' | null
          effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
          banned: ('haiku' | 'sonnet' | 'opus' | 'fable')[]
        } | null
      }>
      /**
       * What the features recorded about their decisions (core/decisions.ts),
       * oldest first, at most 50: what `/dp log` shows. `n` counts the session's
       * decisions from 1.
       */
      decisionLog: { n: number; feature: string; outcome: string; about: string; reason: string }[]
      /** The person's lock on the main agent's effort: wins over every decision; null when unlocked. */
      lock: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
      /**
       * The mid-turn re-decision's own record of a main turn (#5), id
       * `main:<turnId>` (turnKey): its steps, the tool calls they made and how
       * they ended, and when its effort was last asked about.
       */
      midturn: StateFamily<{
        /** Steps the turn has made: the latest step's index + 1. */
        steps: number
        /** The engine's own effort on the latest step; null when the model takes no level (nothing to re-decide). */
        engine: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        /** The step the latest re-decision was asked for; null before the first. */
        askedFor: number | null
        /** The latest steps, oldest first (at most 16): the last text written and the tools called, each with how it ended. */
        recent: {
          index: number
          text: string
          tools: { name: string; detail: string; outcome: 'ok' | 'failed' | 'blocked' | 'denied' }[]
        }[]
      }>
      /** The main agent's step in progress (its tool calls carry no turn id); null before the first. */
      mainStep: { turnId: string; index: number } | null
      /**
       * Each loop's failed tool calls and forced raises (#7), id `main` for the
       * main agent (its counts are those of the turn `turnId`; a new turn starts
       * them afresh) or the agentId of a dispatched or workflow agent (counted
       * for as long as it lives). The one count of failures: the mid-turn
       * re-decision (#5) sends the main agent's in its counts. Written by
       * features/escalation.ts only.
       */
      escalation: StateFamily<{
        /** The main turn the counts belong to; '' for an agent. */
        turnId: string
        /** Tool calls that failed since the loop began (hook blocks and the person's refusals not counted). */
        failures: number
        /** Tool calls a hook refused. */
        hookBlocks: number
        /** The counts when they last started over (a forced raise, failures found expected, nothing left to raise): what is counted is the rest. */
        base: { failures: number; hookBlocks: number }
        /** Forced raises so far (an expected-failure verdict is not one). */
        raises: number
        /** The loop's latest step, the engine's effort and model on it: what a stuck re-decision asked as a call ends reads. */
        step: number | null
        engine: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        model: string | null
        /** The step a stuck re-decision was last asked for; null before the first. */
        askedFor: number | null
        /** An agent's step at its latest forced raise (the main agent's is its turn's `raisedAt`); null before one. */
        raisedAt: number | null
        /** The escalation switch was off when the loop was last seen: what was counted meanwhile is written off once it is on. */
        paused: boolean
      }>
      /**
       * The person's own words this turn, masked and clipped, oldest first: the
       * last message they sent while the session was idle, then the ones they
       * typed while its turn ran (at most 8). A dispatched agent's decision reads
       * them as `user_message`.
       */
      said: string[]
      /**
       * The Workflows the workflow-agents feature sent back to the main agent
       * (return mode), as a hash of each one's name and prompts, oldest first,
       * at most 16: a Workflow is sent back once, its second submission runs.
       */
      returned: string[]
      /**
       * The directories of the session's Workflow runs, as the escalation
       * feature (#7) notes them when a run's tool call returns (newest last, at
       * most 8), whatever the other features' switches say: it reads a workflow
       * agent's transcript there (the engine keeps it from `$.session.messages`).
       */
      workflowRuns: {
        /** The run's id (`runId` of the Workflow tool's result). */
        runId: string
        /** The run's directory (`transcriptDir`): its journal.jsonl, and each agent's transcript. */
        dir: string
      }[]
      /**
       * The Workflow runs of the session, as the workflow-labels feature (#9)
       * records them when the run's tool call returns (newest last, at most 8):
       * it routes their agents as each one starts, by the label the run's
       * journal records for it.
       */
      labelRuns: {
        /** The run's id (`runId` of the Workflow tool's result). */
        runId: string
        /** The run's directory (`transcriptDir`): its journal.jsonl, and each agent's transcript. */
        dir: string
        /** The script's `meta` name and description; null when it has none (or could not be read). */
        workflow: string | null
        description: string | null
        /** The script's agent() calls in order; null when the script could not be read: each agent is decided from its own prompt. */
        sites: {
          /** The line the call starts on. */
          line: number
          /** The label as the script writes it (a template keeps its `${...}`); null when it has none, or works it out when it runs. */
          label: string | null
          /**
           * How a label the journal recorded is told to be this call's: `exact` (a string label),
           * `pattern` (a template label, a regular expression's source), `head` (no label: the engine
           * records the prompt's start, `whole` when the prompt is a string), `none` (nothing to tell it by).
           */
          match: { kind: 'exact'; label: string } | { kind: 'pattern'; source: string } | { kind: 'head'; head: string; whole: boolean } | { kind: 'none' }
          /** `set`: decided when the run started; `runtime`: decided from each agent's prompt as it starts; `script`: left as the script says. */
          route:
            | { kind: 'set'; model: 'haiku' | 'sonnet' | 'opus' | 'fable' | null; effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null }
            | { kind: 'runtime' }
            | { kind: 'script' }
          /** The call's own `model`, `effort` and `agentType` options, for a decision made as its agents start. */
          model: { kind: 'none' } | { kind: 'literal'; value: string } | { kind: 'dynamic' }
          effort: { kind: 'none' } | { kind: 'literal'; value: string } | { kind: 'dynamic' }
          agentType: string | null
          /** The person's terms for the call's work, as its decision read them; its agents' plans keep them. */
          terms: {
            model: 'haiku' | 'sonnet' | 'opus' | 'fable' | null
            effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
            banned: ('haiku' | 'sonnet' | 'opus' | 'fable')[]
          } | null
        }[] | null
      }[]
      /**
       * What the workflow-agents feature (#8) read of the person's terms for
       * each agent() call of a script the main agent sent inline (by the
       * call's index; null for none), id = the Workflow call's tool_use_id.
       * Written before the tool runs, read by the workflow-labels feature (#9)
       * within the same call, so the agents of the calls #8 wrote into get the
       * terms in their plans as they start.
       */
      workflowTerms: StateFamily<({
        model: 'haiku' | 'sonnet' | 'opus' | 'fable' | null
        effort: 'low' | 'medium' | 'high' | 'xhigh' | 'max' | null
        banned: ('haiku' | 'sonnet' | 'opus' | 'fable')[]
      } | null)[]>
      /**
       * Skills the main agent has had described beside a message in this
       * conversation (#10): suggested again, they are only named. Emptied by
       * /compact and /clear.
       */
      skillsShown: string[]
      /**
       * The session's skills (hooks/core/skills.ts `CatalogSkill`), read once
       * per session by the skills feature (#10). The skill-profiles feature
       * (#11, features/skill-profiles.ts) reads it and puts each profile in
       * as it is written. find_skill (#12) reads it, and reads and keeps it
       * itself when the skills feature did not. `file` is the SKILL.md (or
       * command file) found on disk, null when none (a built-in skill);
       * `profileKey` the store key of its profile (core/profiles.ts),
       * `profile` that profile once written (null until then). null: read it
       * again.
       */
      skillCatalog: {
        skills: {
          name: string
          description: string
          by: 'model' | 'person'
          source: string
          file: string | null
          profileKey?: string | null
          profile?: {
            en: { what: string; use_when: string; not_for: string }
            zh: { what: string; use_when: string; not_for: string }
          } | null
        }[]
      } | null
      /**
       * How the skills feature answered the main agent's skill listing, which
       * the engine keeps for the conversation (#10): `withheld` (with the
       * engine's text), `passed`, or `restored`: withheld, then sent beside a
       * message once the `skills` switch went off. null: not answered in
       * this conversation.
       */
      skillListing: { answered: 'withheld' | 'passed' | 'restored'; text: string } | null
    }
  }
}
